// Reprise (bail partiellement signé) : lecture seule du plan figé à la 1re signature.
function _bsdDdtFrozenHtml(plan) {
  if (!(plan && Array.isArray(plan.items))) {
    return `<div class="bsd-state-label">${_uiIcon('attach')} Pièces annexées au bail</div>
      <div class="bsd-ddt-frozen">${_uiIcon('lock', 13)} Bail déjà signé avant l'annexion automatique : aucune pièce ajoutée, le texte signé ne change pas.</div>`;
  }
  const rows = (plan.items || []).filter(it => it.statut !== 'na')
    .map(it => `<div class="bsd-ddt-fz"><span>${escHtml(it.label)}</span><span>${escHtml(_ddtItemTxt(it))}</span></div>`).join('');
  return `<div class="bsd-state-label">${_uiIcon('attach')} Pièces annexées au bail</div>
    <div class="bsd-ddt-frozen">${_uiIcon('lock', 13)} Pièces figées à la 1re signature : le bail déjà signé ne change pas.</div>${rows}`;
}
function _bsdDdtRetry(key) {
  const c = _bsdDdtCtx(); const doc = c && c.log ? _ddtPieceDoc(c.log, key) : null;
  if (doc) { _ddtCheckPiece(doc, true).then(_bsdDdtRender); _bsdDdtRender(); }
}
function _bsdDdtToggle(key, on) { if (_bsdDdt) { _bsdDdt.on[key] = !!on; _bsdDdtRender(); } }
function _bsdDdtNa() { if (_bsdDdt) { _bsdDdt.naOpen = !_bsdDdt.naOpen; _bsdDdtRender(); } }
function _bsdDdtPick(key) {
  if (!_bsdDdt) return;
  const c = _bsdDdtCtx(); const s = c && c.log ? _ddtSuggestDoc(c.log, key) : null;
  _bsdDdt.open = key; _bsdDdt.sel = s ? s.id : null;   // document repéré = présélectionné, JAMAIS rattaché sans confirmation
  _bsdDdtRender();
}
function _bsdDdtPickClose() { if (_bsdDdt) { _bsdDdt.open = null; _bsdDdt.sel = null; _bsdDdtRender(); } }
function _bsdDdtSel(id) { if (_bsdDdt) { _bsdDdt.sel = id; _bsdDdtRender(); } }
function _bsdDdtView(key) {
  const c = _bsdDdtCtx(); const doc = c && c.log ? _ddtPieceDoc(c.log, key) : null;
  if (doc) _handleAttachmentOpen(doc.id);
}
// « Je l'ai déjà » : déclaré détenu HORS application, sur le logement → plus jamais redemandé.
function _bsdDdtDeclare(key) {
  const c = _bsdDdtCtx(); if (!c || !c.log) return;
  _ddtSetDetenu(c.log, key, true); _bsdDdt.on[key] = true; saveDB(); _bsdDdtRender();
  showToast('Noté : pièce détenue hors application. Elle ne sera plus redemandée pour ce logement.', 'ok', 4500);
}
function _bsdDdtUndeclare(key) {
  const c = _bsdDdtCtx(); if (!c || !c.log) return;
  _ddtSetDetenu(c.log, key, false); saveDB(); _bsdDdtRender();
}
function _bsdDdtPickConfirm(key) {
  const c = _bsdDdtCtx(); if (!c || !c.log || !_bsdDdt.sel) return;
  const doc = (DB.documents || []).find(d => d && !d._deleted && String(d.id) === String(_bsdDdt.sel));
  if (!doc) { showToast('Document introuvable', 'err'); return; }
  _ddtSetPiece(c.log, key, doc.id);
  _bsdDdt.on[key] = true; _bsdDdt.open = null; _bsdDdt.sel = null;
  saveDB(); _bsdDdtRender();
  showToast('« ' + (doc.originalName || doc.name) + ' » rattaché au diagnostic.', 'ok', 3500);
}
async function _bsdDdtUpload(key, input) {
  const c = _bsdDdtCtx(); const f = input && input.files && input.files[0];
  if (!c || !c.log || !f) return;
  const max = (typeof ATTACHMENT_DEFAULT_MAX_SIZE !== 'undefined') ? ATTACHMENT_DEFAULT_MAX_SIZE : 10 * 1024 * 1024;
  if (f.size > max) { showToast('Fichier trop lourd : ' + (f.size / 1048576).toFixed(1) + ' Mo (max ' + (max / 1048576) + ' Mo)', 'err', 6000); input.value = ''; return; }
  try {
    const dataB64 = await new Promise((res, rej) => { const r = new FileReader(); r.onload = e => res(e.target.result); r.onerror = () => rej(new Error('lecture du fichier échouée')); r.readAsDataURL(f); });
    const doc = await _attachmentSaveForEntity(
      { type: 'logement', id: c.log.id, ref: c.log.ref, logRef: c.log.ref, category: 'documents' },
      { name: f.name, mime: f.type, size: f.size, dataB64 });
    _ddtSetPiece(c.log, key, doc.id);
    _bsdDdt.on[key] = true; _bsdDdt.open = null; _bsdDdt.sel = null;
    saveDB(); _bsdDdtRender();
    showToast('« ' + f.name + ' » déposé et rattaché au diagnostic.', 'ok', 3500);
  } catch (e) { showToast('Dépôt impossible : ' + ((e && e.message) || 'erreur'), 'err', 6000); }
}

// _bsdSignerRow — scaffold d'UNE rangée signataire du modal d'envoi (bailleur OU locataire). DRY :
// même squelette (.bsd-signer-row / ord / avatar / rôle / email), les contrôles spécifiques au rôle
// (toggle présentiel locataire · case signataire + toggle distance bailleur) sont passés en `controls`,
// la note éventuelle en `extra`. avBg = couleur ord+avatar (bailleur violet), emailHidden masque l'email.
// SECOND FACTEUR SMS (GO 21/10) : mobile d'un signataire À DISTANCE, avec l'avertissement « renseigner le mobile »
// (jamais bloquant : sans mobile, la signature se fait avec le code e-mail seul, et la preuve le note).
function _bsdTelHtml(side, i, tel, visible) {
  const ok = !!(window.ImmoTelephone && window.ImmoTelephone.mobileE164(tel));
  return `<div id="bsd-telw-${side}-${i}"${visible ? '' : ' style="display:none"'}>`
    + `<input class="inp" id="bsd-tel-${side}-${i}" type="tel" inputmode="tel" value="${escHtml(tel || '')}" placeholder="mobile (second code, par SMS)" oninput="_bsdTelMaj('${side}',${i})" style="margin-top:6px">`
    + `<div id="bsd-telnote-${side}-${i}" class="hint" style="font-size:12px;color:var(--t2);margin-top:4px${ok ? ';display:none' : ''}">${_uiIcon('alert', 12)} Renseigner le mobile pour un second facteur (code SMS). Sans mobile, la signature reste possible avec le code e-mail seul.</div></div>`;
}
function _bsdTelMaj(side, i) {
  const el = document.getElementById('bsd-tel-' + side + '-' + i), note = document.getElementById('bsd-telnote-' + side + '-' + i);
  if (el && note) note.style.display = (window.ImmoTelephone && window.ImmoTelephone.mobileE164(el.value)) ? 'none' : '';
}
function _bsdSignerRow(o) {
  const bg = o.avBg ? ' style="background:' + o.avBg + '"' : '';
  return `
      <div class="bsd-signer-row${o.off ? ' bsd-off' : ''}" id="${o.rowId}">
        <div class="bsd-ord"${bg}>${o.ordTxt}</div>
        <div class="bsd-av"${bg}>${escHtml(_bsdInitials(o.nom))}</div>
        <div>
          <div class="bsd-signer-meta">
            <span class="bsd-role">${escHtml(o.role)} · ${escHtml(o.nom)}</span>
            ${o.controls}
          </div>
          <input class="inp" id="${o.emailId}" value="${escHtml(o.emailVal || '')}" placeholder="${escHtml(o.placeholder || 'email du signataire')}"${o.emailHidden ? ' style="display:none"' : ''}>${o.extra || ''}
        </div>
      </div>`;
}

// FIL-ROUGE — sélecteur de mode CLAIR et IDENTIQUE bailleur/locataire (remplace les 2 bascules inversées
// « distance » (bailleur, ON=distance) / « présentiel » (locataire, ON=présentiel) qui prêtaient à confusion :
// un utilisateur mettait le locataire « à distance » et il signait en local). side='b'|'l'. allowNo = co-gérant.
function _bsdModeSeg(side, i, mode, allowNo) {
  const seg = (m, label, bg) => {
    const on = mode === m;
    return `<button type="button" data-m="${m}" onclick="_bsdSetMode('${side}',${i},'${m}')" style="border:1px solid ${on ? bg : 'var(--bd,#e4e7ee)'};background:${on ? bg : 'transparent'};color:${on ? '#fff' : 'var(--t2,#6e7888)'};font:inherit;font-size:11px;font-weight:700;padding:6px 10px;border-radius:6px;cursor:pointer">${label}</button>`;
  };
  return `<div class="bsd-seg" style="display:inline-flex;gap:5px;flex-wrap:wrap">`
    + seg('pres', _uiIcon('person', 14) + ' Présentiel', 'var(--grn,#16a34a)')
    + seg('dist', _uiIcon('send', 14) + ' À distance', 'var(--pur,#7c3aed)')
    + (allowNo ? seg('no', _uiIcon('close', 14) + ' Ne signe pas', '#94a3b8') : '')
    + `<input type="hidden" id="bsd-mode-${side}-${i}" value="${mode}"></div>`;
}
function _bsdSetMode(side, i, mode) {
  // Q1 — garde-fou : au moins un gérant doit signer. Refuser le passage du DERNIER bailleur actif
  // sur « Ne signe pas » (0 signataire bailleur = bail invalide). Filet UX en amont de la garde
  // légale du lancement (« Au moins un signataire côté bailleur est requis »). Bailleur ('b') seul.
  if (side === 'b' && mode === 'no') {
    var _others = Array.prototype.slice.call(document.querySelectorAll('input[id^="bsd-mode-b-"]'))
      .filter(function (el) { return el.id !== 'bsd-mode-b-' + i && el.value !== 'no'; });
    if (!_others.length) { showToast('Au moins un gérant doit signer le bail', 'err', 4000); return; }
  }
  const hid = document.getElementById('bsd-mode-' + side + '-' + i);
  if (hid) hid.value = mode;
  const seg = hid && hid.parentElement;
  if (seg) seg.querySelectorAll('button[data-m]').forEach(btn => {
    const m = btn.getAttribute('data-m'), on = m === mode;
    const bg = m === 'pres' ? 'var(--grn,#16a34a)' : (m === 'dist' ? 'var(--pur,#7c3aed)' : '#94a3b8');
    btn.style.background = on ? bg : 'transparent';
    btn.style.color = on ? '#fff' : 'var(--t2,#6e7888)';
    btn.style.borderColor = on ? bg : 'var(--bd,#e4e7ee)';
  });
  const email = document.getElementById((side === 'b' ? 'bsd-bemail-' : 'bsd-email-') + i);
  if (email) { email.style.display = (mode === 'dist') ? '' : 'none'; if (mode !== 'dist') email.classList.remove('err'); }
  const telw = document.getElementById('bsd-telw-' + side + '-' + i);
  if (telw) telw.style.display = (mode === 'dist') ? '' : 'none';
  if (side === 'b') {   // co-gérant : note « signe dans l'app » + grisage de la ligne si « ne signe pas »
    const note = document.getElementById('bsd-bnote-' + i);
    if (note) note.style.display = (mode === 'pres') ? '' : 'none';
    const row = document.getElementById('bsd-brow-' + i);
    if (row) row.classList.toggle('bsd-off', mode === 'no');
    const ord = row && row.querySelector('.bsd-ord');
    if (ord) ord.textContent = (mode === 'no') ? '—' : String(i + 1);
  }
}

// D2a — Co-gérants signataires du bail + leur état de signature.
// Retourne [{ idx, nom, mode:'pres'|'dist'|'no', email }] parallèle à getBailSignataires(bail, ent).
// État persisté dans bail.bailleurSign[i] (parallèle aux noms). Défaut (absent) = 'pres' (présentiel
// in-app) → comportement actuel préservé. Cas mandataire (signe p/o le bailleur) : reste présentiel
// in-app en v1 (pas d'envoi distant) → liste vide.
// SIGNATURE-SMOKE S1 — la liste passe par le résolveur PARTAGÉ (window.BailSignataires) : plus
// aucune dérivation locale des ids/noms. « Liste vide » signifie désormais UNIQUEMENT « mandataire »
// (cas verrouillé présentiel in-app). Une entité SANS gérant renvoie 1 signataire de repli
// (id bailleur-0, au nom de l'entité) — avant, elle renvoyait [] et était confondue avec le
// mandataire, ce qui faisait demander un signataire 'bailleur' absent du document.
function _bailBailleurSigners(bail) {
  if (!bail) return [];
  // Garde explicite (audit 13/08) : sur la chaîne SIGNATURE, mieux vaut un message clair qu'un
  // TypeError opaque ou, pire, un repli local qui ferait diverger à nouveau les identités.
  if (!window.BailSignataires) throw new Error('Module signataires non chargé (js/helpers/bail-signataires.global.js) — recharger la page (Ctrl+Shift+R) avant de signer.');
  const withMand = !!(bail.withMandataire && DB.params && DB.params.mandataire && DB.params.mandataire.actif && DB.params.mandataire.nom);
  if (withMand) return [];
  const ent = (DB.entites || []).find(e => e && e.nom === bail.entity) || {};
  const names = (typeof getBailSignataires === 'function' ? getBailSignataires(bail, ent) : []) || [];
  const states = Array.isArray(bail.bailleurSign) ? bail.bailleurSign : [];
  const resolved = window.BailSignataires.resolveBailleurSigners({
    names, withMandataire: false, entityLabel: ent.nom || bail.entity || ''
  });
  return resolved.map((s, i) => {
    const st = states[i] || {};
    const stMode = (st.mode === 'dist' || st.mode === 'no') ? st.mode : 'pres';
    // Q1 — un gérant UNIQUE ne peut pas « ne pas signer » (bail sans signature bailleur = invalide).
    // Auto-répare un état 'no' résiduel (ex. co-gérant retiré de l'entité après un envoi à 2 gérants) :
    // le seul signataire restant repasse en présentiel plutôt que de rester bloqué au lancement.
    const mode = (stMode === 'no' && resolved.length <= 1) ? 'pres' : stMode;
    return { idx: i, id: s.id, kind: s.kind, nom: s.nom, mode, email: (st.email || '').trim(), tel: (st.tel || '').trim() };
  });
}

// _collectSide — pousse dans `out` les signataires DISTANTS d'un côté (bailleur OU locataire). DRY :
// même bloc appelé pour les deux. sigId = prefix-<rang parmi les distants du même côté> (aligné
// computeSigId relais + ancres PDF) ; ordre = position combinée 1-based. distantFn(item)→bool ·
// labelFn(i,rank)→nom de repli si nom vide.
function _collectSide(out, items, prefix, role, distantFn, labelFn) {
  let rank = 0;
  (items || []).forEach((it, i) => {
    if (!distantFn(it)) return;
    // nomBail : le nom RÉEL du bail (jamais le libellé de repli « Locataire 1 ») — le relais l'impose au signataire.
    out.push({ sigId: prefix + '-' + rank, role: role, nom: (it && it.nom) || labelFn(i, rank), nomBail: (it && it.nom) ? String(it.nom).trim() : '', email: ((it && it.email) || '').trim(), tel: ((it && it.tel) || '').trim(), distant: true, ordre: out.length + 1, bailIdx: i });
    rank++;
  });
}

// D. Collecte des signataires DISTANTS : BAILLEURS distants d'abord, puis LOCATAIRES distants.
function _collectRemoteSigners(bail) {
  const out = [];
  _collectSide(out, _bailBailleurSigners(bail), 'bailleur', 'bailleur', b => b.mode === 'dist', (i, rank) => 'Co-gérant ' + (rank + 1));
  const locs = (Array.isArray(bail.locataires) && bail.locataires.length)
    ? bail.locataires
    : [{ nom: bail.nom, email: bail.email }];
  _collectSide(out, locs, 'loc', 'locataire', l => !(l && l.presentiel), (i) => 'Locataire ' + (i + 1));
  return out;
}

// ─── BAIL-EN-COURS-SIGNE-HORS-PROPRYO §3.2 : contrôle PRÉALABLE de l'état RÉEL de la session au relais ───
// Commun à « Relancer » (openRemoteSignModal), « Annuler la session » et « Signé hors Propryo » : on ne détruit/archive
// JAMAIS une session dont on ne sait pas si elle porte une signature (fail-closed légal, audit 2026-07-15 défaut D2).
//  • completed            → la signature est RÉCUPÉRÉE (_completeRemoteSign) : { ok:false, recupere:true }, rien n'est annulé
//  • 404 → 'expired'      → rien à perdre : { ok:true, etat:'expired' }
//  • pending/sent/chaining → session vivante : confirmation (opts.confirmMsg ; sans message, l'appelant confirme lui-même)
//                            puis { ok:true, etat:'pending-invalidee' }
//  • injoignable, accès perdu, statut inattendu → REFUS { ok:false, raison } (on ne touche à rien)
// Aucun effet sur le relais ici : l'appelant appelle `purge()` (suppression best-effort) quand il passe réellement à l'acte.
async function _rsPreflight(ref, opts) {
  const o = opts || {};
  const bail = DB.baux && DB.baux[ref];
  const rs = bail && bail.signatures && bail.signatures.remoteSession;
  const rien = async function () { return { ok: true, etat: 'aucune' }; };
  // Une complétion (récupération de la signature) est EN COURS pour ce bail : on ne touche à rien (audit d'intégration 🟠1).
  if (window.__remoteCompleting && window.__remoteCompleting[ref]) {
    showToast('Une signature à distance est en cours de récupération pour ce bail : rien n\'a été modifié. Réessayer dans un instant.', 'err', 9000);
    return { ok: false, raison: 'completion-en-cours' };
  }
  if (!rs || !rs.sessionId) return { ok: true, etat: 'aucune', rs: rs || null, base: '', purge: rien };
  const base = _resolveRelayBase(rs);
  // On n'exige QUE le sessionId : un ownerToken absent est précisément le scénario §6 (accès perdu) ; sans jeton on ne peut rien
  // vérifier → état indéterminé → access-lost.
  let reel;
  if (!rs.ownerToken) { reel = { status: 'access-lost' }; }
  else try { reel = await _bsRelayPollSession(base, rs.sessionId, rs.ownerToken); }
  catch (e) {
    console.warn('[remoteSign] pré-vol échoué', e);
    showToast('Impossible de vérifier l\'état de la session existante (relais injoignable). On ne touche à rien tant qu\'on n\'a pas confirmé qu\'aucune signature n\'existe — réessayer dans un instant.', 'err', 8000);
    return { ok: false, raison: 'injoignable' };
  }
  // §6 — accès propriétaire perdu : on ne sait PAS si ce bail a déjà été signé → on n'écrase RIEN ; le badge propose « Récupérer l'accès ».
  if (reel && reel.status === 'access-lost') {
    rs.status = 'access-lost';
    saveDB(); _refreshAfterMutation();
    showToast('Accès perdu à la session de signature existante : impossible de vérifier si ce bail a déjà été signé. On ne touche à rien. Utiliser « 🔑 Récupérer l\'accès » sur la ligne du bail.', 'err', 9000);
    return { ok: false, raison: 'acces-perdu' };
  }
  if (reel && reel.status === 'completed') {
    showToast('✅ Ce bail a déjà été signé à distance — récupération de la signature en cours…', 'info', 4000);
    try { await _completeRemoteSign(ref, reel); saveDB(); _refreshAfterMutation(); showToast('Signature récupérée : le bail est signé.', 'ok', 5000); }
    catch (e) { console.warn('[remoteSign] récupération au pré-vol', e); showToast('Récupération du bail signé impossible — réessayer « Vérifier »', 'err', 6000); }
    return { ok: false, recupere: true, raison: 'completed' };
  }
  if (reel && ['pending', 'sent', 'chaining'].includes(reel.status)) {
    if (o.confirmMsg && !confirm2(o.confirmMsg)) return { ok: false, raison: 'refuse-par-utilisateur' };
  }
  // LISTE BLANCHE : 'expired' (404 = rien à perdre) ou pending/sent/chaining. Tout le reste (réponse nulle, corps illisible, statut
  // inattendu) = indéterminé → on ne détruit RIEN.
  if (!reel || !['expired', 'pending', 'sent', 'chaining'].includes(reel.status)) {
    console.warn('[remoteSign] pré-vol : statut relais inattendu', reel);
    showToast('État de la session existante indéterminé — on ne touche à rien tant qu\'on n\'a pas confirmé qu\'aucune signature n\'existe. Réessayer dans un instant.', 'err', 8000);
    return { ok: false, raison: 'indetermine' };
  }
  const vivante = reel.status !== 'expired';
  return {
    ok: true, etat: vivante ? 'pending-invalidee' : 'expired', rs, base,
    // Purge GARDÉE : l'état est relu au relais juste avant le DELETE (jamais une suppression sur la foi de ce pré-vol).
    purge: function () { return _rsPurgeGardee(base, rs); }
  };
}

// ─── Audit d'intégration v15.728 🟠1 / 🟠2 : PURGE GARDÉE, VÉRIFIÉE, RETENTÉE ───
// Le DELETE du relais détruit la session ET le PDF signé, QUEL QUE SOIT leur statut (relay/src/index.js, storage.js). Juste
// avant de supprimer, on relit donc l'état RÉEL : completed → on ne supprime RIEN (la signature est à récupérer) ; expired /
// pending / sent / chaining → DELETE, réussi seulement sur 204 ou 404 ; tout le reste (injoignable, accès perdu, statut
// inattendu) → on ne supprime pas. Ne lève jamais.
// @returns {Promise<{ok:boolean, etat:string, state?:object, rs:object, base:string}>}
async function _rsPurgeGardee(base, rs) {
  const out = (ok, etat, state) => ({ ok, etat, state, rs, base });
  if (!rs || !rs.sessionId) return out(true, 'aucune');
  if (!rs.ownerToken) return out(false, 'sans-jeton');
  let reel;
  try { reel = await _bsRelayPollSession(base, rs.sessionId, rs.ownerToken); }
  catch (e) { console.warn('[remoteSign] purge : relais injoignable', e); return out(false, 'injoignable'); }
  if (reel && reel.status === 'completed') return out(false, 'completed', reel);
  if (!reel || !['expired', 'pending', 'sent', 'chaining'].includes(reel.status)) return out(false, (reel && reel.status) || 'indetermine');
  let supprimee = false;
  try { supprimee = (await _bsRelayDeleteSession(base, rs.sessionId, rs.ownerToken)) === true; } catch (e) { supprimee = false; }
  return supprimee ? out(true, 'supprimee') : out(false, 'echec-suppression');
}
// L'entrée d'archive (bail.signaturesAnnulees) de cette session — la plus récente.
function _rsArchiveDeSession(bail, sessionId) {
  const L = bail && Array.isArray(bail.signaturesAnnulees) ? bail.signaturesAnnulees : [];
  for (let i = L.length - 1; i >= 0; i--) {
    const s = L[i] && L[i].signatures && L[i].signatures.remoteSession;
    if (s && s.sessionId === sessionId) return L[i];
  }
  return null;
}
// File des purges à retenter : sur CET appareil seulement (localStorage hors base). Le jeton propriétaire du relais n'est pas
// recopié dans les archives du bail, qui partent chez les membres de la SCI (🟡9) : il ne vit qu'ici.
function _rsPurgesLire() {
  try { const a = JSON.parse(localStorage.getItem(_lsKey('immotrack_rs_purges')) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; }
}
function _rsPurgesEcrire(a) {
  try { if (a && a.length) localStorage.setItem(_lsKey('immotrack_rs_purges'), JSON.stringify(a)); else localStorage.removeItem(_lsKey('immotrack_rs_purges')); } catch (e) {}
}
// Purge d'une session ARCHIVÉE en échec : marqueur `purgeEchouee` sur l'archive (synchronisé, sans jeton), mise en file du nouvel
// essai (_rsPurgesRetenter, au prochain passage de _pollRemoteSignSessions), et on le DIT.
function _rsPurgeEchouee(ref, pr) {
  const rs = pr && pr.rs; if (!rs || !rs.sessionId) return;
  const bail = DB.baux && DB.baux[ref];
  const arch = _rsArchiveDeSession(bail, rs.sessionId);
  if (arch) { arch.purgeEchouee = true; arch.purgeTenteeLe = new Date().toISOString(); _stamp(bail); try { saveDB(); } catch (e) {} }
  const file = _rsPurgesLire().filter(x => x && x.sessionId !== rs.sessionId);
  file.push({ ref, base: pr.base || '', sessionId: rs.sessionId, ownerToken: rs.ownerToken || '', createdAt: rs.createdAt || null, ajouteLe: new Date().toISOString() });
  _rsPurgesEcrire(file);
  showToast('La session de signature à distance n\'a pas pu être supprimée du relais (' + (pr.etat === 'injoignable' ? 'relais injoignable' : 'suppression refusée') + ') : nouvel essai automatique au prochain passage. Le bail, lui, est bien enregistré.', 'warn', 9000);
}
// Nouvel essai des purges en file (appelé par _pollRemoteSignSessions). true = la base a changé (marqueur levé, signature récupérée).
async function _rsPurgesRetenter() {
  const file = _rsPurgesLire();
  if (!file.length || window.__rsPurgesEnCours) return false;
  window.__rsPurgesEnCours = true;
  const reste = []; let mute = false;
  try {
    for (const x of file) {
      if (!x || !x.sessionId) continue;
      const bail = DB.baux && DB.baux[x.ref];
      const t0 = Date.parse(x.createdAt || x.ajouteLe || '');
      // Le relais RÉARME son TTL (14 j) à chaque écriture : une session signée au 13e jour vit jusqu'au ~27e. On relit donc
      // toujours l'état (un 404 = expirée → sortie de la file) ; l'abandon sans relecture n'intervient qu'au-delà de 2 TTL + 1 j,
      // quand plus aucune session ne peut exister (relectures Fable 14/10).
      const pr = (!isNaN(t0) && Date.now() - t0 > 2 * REMOTE_SIGN_TTL_MS + 86400000) ? { ok: true, etat: 'ttl' } : await _rsPurgeGardee(x.base, x);
      if (pr.etat === 'completed') { if (await _rsRecupererApresArchivage(x.ref, x, pr.state)) mute = true; continue; }
      if (!pr.ok) { reste.push(x); continue; }
      const a = _rsArchiveDeSession(bail, x.sessionId);
      if (a && a.purgeEchouee) { delete a.purgeEchouee; a.purgeeLe = new Date().toISOString(); _stamp(bail); mute = true; }
    }
  } catch (e) { console.warn('[remoteSign] nouvel essai des purges', e); }
  finally { window.__rsPurgesEnCours = false; }
  _rsPurgesEcrire(reste.concat(_rsPurgesLire().filter(y => y && !file.some(x => x && x.sessionId === y.sessionId))));
  return mute;
}
// Une session ARCHIVÉE (annulée, ou remplacée par « signé hors Propryo ») était en réalité SIGNÉE au relais (le locataire a signé
// pendant l'opération) : l'annulation / la déclaration est abandonnée (une déclaration abandonnée est archivée à son tour, rien n'est
// perdu), la session est rétablie et la signature électronique récupérée (_completeRemoteSign) — puis on le DIT. true = récupérée.
async function _rsRecupererApresArchivage(ref, rs, state) {
  const bail = DB.baux && DB.baux[ref];
  const arch = bail && rs ? _rsArchiveDeSession(bail, rs.sessionId) : null;
  if (!arch) {
    showToast('Le locataire a signé à distance une session déjà archivée, introuvable sur ce bail : la signature reste au relais. Ne rien supprimer et contacter le support.', 'err', 12000);
    return false;
  }
  const B = window.BailSignatureEtat;
  const declaration = !!(bail.signatures && bail.signatures.mode === 'externe');
  const annulees = bail.signaturesAnnulees.filter(a => a !== arch);
  if (declaration && B) {
    const r = B.retirerSignatureExterne(bail, { now: new Date(), auteur: _bailAuteurCourant(), motif: 'externe-retire' });
    if (r.archive) { r.archive.raison = 'signe-a-distance-pendant-la-declaration'; annulees.push(r.archive); }
  }
  const sg = JSON.parse(JSON.stringify(arch.signatures));
  sg.remoteSession = Object.assign({}, sg.remoteSession || {}, { ownerToken: rs.ownerToken });
  bail.signatures = sg;
  if (annulees.length) bail.signaturesAnnulees = annulees; else delete bail.signaturesAnnulees;
  _stamp(bail);
  try { await _completeRemoteSign(ref, state); }
  catch (e) {
    console.warn('[remoteSign] récupération après archivage', e);
    try { saveDB(); _refreshAfterMutation(); } catch (_e) {}
    showToast('Le locataire a signé à distance pendant l\'opération : la session est rétablie mais la récupération du bail signé a échoué — utiliser « Vérifier » sur la ligne du bail.', 'err', 12000);
    return true;
  }
  try { saveDB(); _refreshAfterMutation(); } catch (e) {}
  showToast('Le locataire a signé à distance pendant l\'opération : la signature électronique est récupérée, le bail est signé. '
    + (declaration ? 'La déclaration « signé hors Propryo » est abandonnée (conservée dans l\'historique du bail).' : 'L\'annulation de la session est abandonnée.'), 'ok', 12000);
  return true;
}
// Déclaration « signé hors Propryo » sur un bail porteur d'une session à distance : l'état RÉEL est relu au relais JUSTE AVANT
// l'enregistrement (le locataire a pu signer depuis l'ouverture de la fenêtre). '' = on continue ; 'completion' = refus (récupération
// en cours) ; 'controle' = contrôle lancé, `relancer` (saveBail) est rappelé s'il passe. Une signature trouvée est récupérée et la
// déclaration abandonnée, et on le dit.
function _bailExterneRecontrole(editRef, ext, relancer) {
  if (!ext || ext.action !== 'declarer' || !editRef) return '';
  const ex = DB.baux && DB.baux[editRef];
  const rs = ex && ex.signatures && ex.signatures.remoteSession;
  if (!rs || !rs.sessionId) return '';
  if (window.__remoteCompleting && window.__remoteCompleting[editRef]) {
    showToast('Une signature à distance est en cours de récupération pour ce bail : rien n\'a été modifié. Réessayer dans un instant.', 'err', 9000);
    return 'completion';
  }
  const _jeton = window.__bailExtRecontrole; window.__bailExtRecontrole = null;   // jeton à usage unique, valable pour le passage relancé seulement
  if (_jeton && _jeton.ref === editRef && Date.now() - _jeton.t < 3000) return '';
  (async function () {
    const pf = await _rsPreflight(editRef);
    if (!pf.ok) {
      if (pf.recupere) {
        try { _closeBailWizard(); } catch (e) {}
        showToast('Le locataire a signé à distance entre-temps : la signature électronique est récupérée, le bail est signé. La déclaration « signé hors Propryo » est abandonnée — rien n\'a été enregistré.', 'ok', 12000);
      }
      return;   // injoignable, accès perdu, indéterminé, récupération en cours : _rsPreflight l'a dit ; rien n'est enregistré
    }
    window._bailExtEtatRelais = pf.etat; window._bailExtPurge = pf.purge; window.__bailExtRecontrole = { ref: editRef, t: Date.now() };
    relancer();
  })();
  return 'controle';
}

// Fenêtre « Annuler la session de signature ? » (maquette signature-expiree-confirm). Promise<boolean> : true = annuler.
function _rsConfirmAnnulation(html) {
  return new Promise(function (resolve) {
    const old = document.getElementById('ov-rs-annul'); if (old) old.remove();
    window.__rsAnnulFin = function (ok) { const f = window.__rsAnnulFin; window.__rsAnnulFin = null; if (!f) return; closeM('ov-rs-annul'); setTimeout(function () { const o = document.getElementById('ov-rs-annul'); if (o) o.remove(); }, 250); resolve(!!ok); };
    document.body.insertAdjacentHTML('beforeend',
      '<div class="ov" id="ov-rs-annul" onclick="if(event.target===this&&window.__rsAnnulFin)window.__rsAnnulFin(false)">'
      + '<div class="modal" style="max-width:480px">'
      + '<div class="m-head"><h3>Annuler la session de signature ?</h3><button class="m-close" onclick="window.__rsAnnulFin&&window.__rsAnnulFin(false)">✕</button></div>'
      + '<div class="m-body">' + html + '</div>'
      + '<div class="m-foot"><button class="btn bs" onclick="window.__rsAnnulFin&&window.__rsAnnulFin(false)">Garder la session</button>'
      + '<button class="btn bp" id="rs-annul-ok" onclick="window.__rsAnnulFin&&window.__rsAnnulFin(true)">Annuler la session</button></div>'
      + '</div></div>');
    openM('ov-rs-annul');
  });
}

// « Annuler la session » (session expirée / en erreur) : le bail redevient NON SIGNÉ ; la session, et la signature déjà recueillie
// (ex. le bailleur avait signé dans l'app), sont ARCHIVÉES dans bail.signaturesAnnulees — rien n'est détruit. Décision Didier 06/10 (a).
async function annulerSessionSignature(ref) {
  const bail = DB.baux && DB.baux[ref];
  const rs = bail && bail.signatures && bail.signatures.remoteSession;
  if (!bail || !rs) { showToast('Aucune session de signature à annuler', 'warn'); return; }
  if (!['expired', 'error'].includes(rs.status)) { showToast('Cette session n\'est pas expirée : on ne l\'annule pas d\'ici.', 'warn', 6000); return; }
  const st = _bailEtatSig(bail);
  if (st.conclu) { showToast('Ce bail est déjà signé : rien à annuler', 'err'); return; }
  const pf = await _rsPreflight(ref);   // sans confirmMsg : la fenêtre ci-dessous confirme (et dit si le lien est encore actif)
  if (!pf.ok) return;
  const sg = bail.signatures;
  const signers = Array.isArray(rs.signers) ? rs.signers : [];
  const noms = signers.filter(x => x && x.role !== 'bailleur' && x.nom).map(x => x.nom);
  const qui = noms.length ? noms.join(', ') : (bail.nom || 'le locataire');
  const envoyee = rs.createdAt ? ' (envoyée le ' + fd(String(rs.createdAt).slice(0, 10)) + ')' : '';
  const bailleurAvaitSigne = !!(sg.signedBailleurAt || (sg.finales && Object.keys(sg.finales).length) || signers.some(x => x && x.role === 'bailleur' && x.signedAt));
  const vivante = pf.etat === 'pending-invalidee';
  const html = '<p style="margin:0 0 12px">La session de signature à distance de <b>' + escHtml(qui) + '</b>' + envoyee
    + (vivante ? ' est <b>encore active</b> au relais : son lien sera invalidé. Elle sera annulée' : ' a expiré. Elle sera annulée')
    + ' et le bail redeviendra <b>non signé</b>.</p>'
    + (bailleurAvaitSigne ? '<p class="mu sm" style="margin:0 0 12px">La signature du bailleur déjà recueillie est archivée dans l\'historique du bail : elle ne servira plus, le bailleur signera de nouveau lors d\'une relance.</p>' : '')
    + '<p class="mu sm" style="margin:0">Rien n\'est supprimé du bail. Une signature à distance peut être relancée, ou le bail déclaré signé hors Propryo, à tout moment.</p>';
  if (!(await _rsConfirmAnnulation(html))) return;
  // 🟠1 (audit d'intégration) : la fenêtre a pu rester ouverte longtemps — l'état RÉEL est relu au relais JUSTE avant d'annuler.
  const pf2 = await _rsPreflight(ref);
  if (!pf2.ok) {
    if (pf2.recupere) showToast('Le locataire a signé à distance pendant la fenêtre : la signature électronique est récupérée, le bail est signé. L\'annulation de la session est abandonnée.', 'ok', 12000);
    return;
  }
  const _etatRelais = pf2.etat === 'pending-invalidee' ? 'pending-invalidee' : 'expired';
  const B = window.BailSignatureEtat;
  const r = B ? B.archiverSignatures(bail, { now: new Date(), auteur: _bailAuteurCourant(), motif: 'session-annulee', etatRelais: _etatRelais }) : { archive: null };
  if (!r.archive) { showToast('Annulation impossible : module de signature indisponible', 'err'); return; }
  const _prevAnn = bail.signaturesAnnulees, _prevMod = bail._modifiedAt;
  bail.signaturesAnnulees = (Array.isArray(bail.signaturesAnnulees) ? bail.signaturesAnnulees : []).concat([r.archive]);
  delete bail.signatures;
  _stamp(bail);
  let _okA; try { _okA = saveDB(); } catch (_e) { console.warn('[annuler session] saveDB', _e); _okA = false; }
  if (_okA === false) {   // écriture refusée (hors ligne, stockage plein) : tout est remis, et la session du relais n'est PAS purgée
    bail.signatures = sg;
    if (_prevAnn === undefined) delete bail.signaturesAnnulees; else bail.signaturesAnnulees = _prevAnn;
    bail._modifiedAt = _prevMod;
    showToast('Session NON annulée : la sauvegarde a échoué — rien n\'a été modifié, la session reste en place. ' + (window.__immoHorsLigne ? 'Hors ligne : réessayer une fois la connexion rétablie.' : 'Stockage indisponible ou plein.'), 'err', 9000);
    return;
  }
  _auditLog('update', 'bail', ref, ref + ' : session de signature à distance annulée (' + (_etatRelais === 'pending-invalidee' ? 'lien invalidé' : 'expirée') + ')');
  saveDB();   // le journal d'audit ci-dessus part avec la même écriture
  if (typeof _refreshAfterMutation === 'function') _refreshAfterMutation();
  // Purge GARDÉE (état relu juste avant le DELETE) : signée entre-temps → l'annulation est abandonnée et la signature récupérée.
  const pr = await pf2.purge();
  if (pr && pr.etat === 'completed') { await _rsRecupererApresArchivage(ref, pr.rs, pr.state); return; }
  showToast('Session annulée : le bail est non signé (l\'ancienne session est conservée dans l\'historique)', 'ok', 7000);
  if (pr && !pr.ok) _rsPurgeEchouee(ref, pr);
}

// « Signé hors Propryo » depuis la session expirée : même contrôle préalable, puis la déclaration de « Modifier le bail »
// (case pré-cochée, origine 'session-expiree'). La session relais n'est supprimée qu'à l'ENREGISTREMENT (annuler la fenêtre ne détruit rien).
async function sessionExpireeSigneHors(ref) {
  const bail = DB.baux && DB.baux[ref];
  const rs = bail && bail.signatures && bail.signatures.remoteSession;
  if (!bail || !rs) { showToast('Aucune session de signature', 'warn'); return; }
  if (_bailEtatSig(bail).conclu) { showToast('Ce bail est déjà signé', 'err'); return; }
  const pf = await _rsPreflight(ref, { confirmMsg: 'La session de signature à distance est encore active au relais.\n\nDéclarer le bail signé hors Propryo invalidera son lien. Continuer ?' });
  if (!pf.ok) return;
  // La case est masquée dans « Modifier le bail » tant qu'une session existe : ici l'état réel vient d'être contrôlé, on l'affiche.
  _bailOuvrirDeclarationExterne(ref, 'session-expiree', { etatRelais: pf.etat, purge: pf.purge, afficherCase: true });
}
// « Modifier le bail » ouvert sur la déclaration « Signé hors Propryo » (case cochée, étape qui la porte). Partagé par la session
// expirée (ci-dessus) et par l'Accueil (« Signé sur papier », MATRICE-ACCUEIL). Rien n'est enregistré avant « Enregistrer ».
// Un bail porteur d'une session de signature à distance passe par sessionExpireeSigneHors (état réel relu au relais d'abord).
function _bailOuvrirDeclarationExterne(ref, origine, o) {
  const opts = o || {};
  const bail = DB.baux && DB.baux[ref];
  if (!opts.afficherCase && bail && bail.signatures && bail.signatures.remoteSession && typeof sessionExpireeSigneHors === 'function') { sessionExpireeSigneHors(ref); return; }
  openBail(ref);
  window._bailExtOrigine = origine || null; window._bailExtEtatRelais = opts.etatRelais || null; window._bailExtPurge = opts.purge || null;
  if (opts.afficherCase) {
    const _fg = el('b-externe-fg'); if (_fg) _fg.style.display = '';
    const _nrs = el('b-externe-rs'); if (_nrs) _nrs.style.display = 'none';
  }
  const chk = el('b-externe');
  if (chk) {
    chk.checked = true; _bailExterneToggle();
    try {   // l'assistant « Modifier le bail » est en étapes : aller à celle qui porte la case
      const pan = chk.closest('.tab-panel'), tous = Array.prototype.slice.call(document.querySelectorAll('#ov-bail .tab-panel')), k = tous.indexOf(pan);
      if (k >= 0 && typeof goBailStep === 'function') goBailStep(k + 1);
      chk.scrollIntoView({ block: 'center' });
    } catch (e) {}
  }
}

// B. Ouvre la modale d'envoi (ou le repli « relais non configuré »).
// async (§4) : pré-vol non destructif avant toute relance — on vérifie l'état RÉEL de l'ancienne session.
async function openRemoteSignModal(ref) {
  const bail = DB.baux[ref];
  const log = DB.logements.find(l => l.ref === ref);
  if (!bail) { showToast('Bail introuvable', 'err'); return; }
  // D2a — verrou 'bailleur-seul' levé : on peut envoyer un bail non signé si un bailleur signe à distance
  // (sa case part vide + ancrée, remplie par le relais). Le bouton d'entrée (fiche/rBaux) décide quand l'offrir.
  bail.signatures = bail.signatures || {};
  if (bail.signatures.signedAt && bail.signatures.mode !== 'bailleur-seul') {
    showToast(bail.signatures.mode === 'externe' ? 'Bail déclaré signé hors Propryo : rien à signer dans Propryo' : 'Ce bail est déjà signé', 'err'); return;
  }
  // ⚠️ §4 RELANCE NON DESTRUCTRICE (audit 2026-07-15, défaut D2). AVANT d'écraser/supprimer l'ancienne
  // session, on VÉRIFIE son état réel (poll avec base résolue §2). Cas :
  //  • completed → la session était SIGNÉE (faux « expirée » du bug relayUrl vide) → on RÉCUPÈRE la
  //    signature (_completeRemoteSign) au lieu de relancer → un document légal signé ne peut plus être
  //    détruit par ce chemin.
  //  • pending/sent/chaining → session vivante non signée → confirmer le remplacement (perte des
  //    signatures partielles).
  //  • expired (404) → session absente du relais, rien à perdre → on relance.
  //  • poll en ERREUR (relais injoignable) → état INDÉTERMINÉ → on N'ÉCRASE PAS (fail-closed légal).
  const _pf = await _rsPreflight(ref, { confirmMsg: 'Une session de signature à distance est déjà en cours pour ce bail.\n\nLa remplacer créera un nouveau lien et invalidera l\'ancien (les signatures déjà recueillies seraient perdues). Continuer ?' });
  if (!_pf.ok) return;
  // La session relais remplacée est supprimée — purge GARDÉE : signée entre-temps → on récupère la signature, pas de relance.
  const _pr = await _pf.purge();
  if (_pr && _pr.etat === 'completed') {
    try { await _completeRemoteSign(ref, _pr.state); saveDB(); _refreshAfterMutation(); showToast('Le locataire a signé à distance entre-temps : la signature est récupérée, le bail est signé. Aucune relance.', 'ok', 9000); }
    catch (e) { console.warn('[remoteSign] récupération avant relance', e); showToast('Récupération du bail signé impossible — réessayer « Vérifier »', 'err', 6000); }
    return;
  }
  if (_pr && !_pr.ok && _pr.etat !== 'aucune') {   // l'ancienne session ne sera plus référencée par le bail : seul le nouvel essai la supprimera
    const _f = _rsPurgesLire().filter(x => x && x.sessionId !== _pr.rs.sessionId);
    _f.push({ ref, base: _pr.base || '', sessionId: _pr.rs.sessionId, ownerToken: _pr.rs.ownerToken || '', createdAt: _pr.rs.createdAt || null, ajouteLe: new Date().toISOString() });
    _rsPurgesEcrire(_f);
  }
  // Repli : pas connecté (pas de jeton de session) → impossible d'appeler le relais. En cloud, l'utilisateur
  // est connecté → ce repli ne s'affiche pas (plus aucune clé à « configurer »).
  const _rcfg = (typeof _relayCfg === 'function') ? _relayCfg() : null;
  if (!(_rcfg && window._relayConfigured && window._relayConfigured(_rcfg))) {
    const cfgHtml = `
      <div class="ov" id="ov-send-cfg" onclick="closeBg(event,'ov-send-cfg')">
        <div class="modal" style="max-width:520px">
          <div class="m-head"><h3>${_uiIcon('send')} Envoyer pour signature</h3><button class="m-close" onclick="closeM('ov-send-cfg')">✕</button></div>
          <div class="m-body">
            <div class="bsd-banner bsd-banner-warn">${_uiIcon('settings')} <div><b>Relais non configuré.</b> Avant le premier envoi, renseigner l'URL du relais et la clé d'application dans les Réglages.</div></div>
            <p class="mu sm" style="font-size:13px;color:var(--t2)">C'est une opération unique. Ensuite, l'envoi se fait en un clic depuis n'importe quelle fiche.</p>
          </div>
          <div class="m-foot">
            <button class="btn bs" onclick="closeM('ov-send-cfg')">Fermer</button>
          </div>
        </div>
      </div>`;
    const oldCfg = document.getElementById('ov-send-cfg'); if (oldCfg) oldCfg.remove();
    document.body.insertAdjacentHTML('beforeend', cfgHtml);
    openM('ov-send-cfg');
    return;
  }

  const locs = _bsdLocataires(bail);
  const adresse = (log && log.adr) || ref;
  const entLabel = bail.entity || 'Bailleur';

  // D2a — section 🏛️ bailleur : 1 row par co-gérant, tri-état (signataire ? + présentiel/distance + email).
  const bSigners = _bailBailleurSigners(bail);   // [] si mandataire → row verrouillée présentiel in-app
  const bRows = bSigners.map((b, i) => {
    const signe = b.mode !== 'no';
    const dist = b.mode === 'dist';
    const controls = _bsdModeSeg('b', i, b.mode, bSigners.length > 1);   // 🟢 Présentiel · 🟣 À distance · ⊘ Ne signe pas (option cachée si un seul gérant — Q1)
    const extra = `<div id="bsd-bnote-${i}" style="font-size:11px;margin-top:2px;color:var(--grn)${signe && !dist ? '' : ';display:none'}">${_uiIcon('check', 13)} Signe dans l'app — pas d'envoi</div>`;
    return _bsdSignerRow({ rowId: `bsd-brow-${i}`, ordTxt: signe ? (i + 1) : '—', avBg: 'var(--pur,#7c3aed)', role: 'Bailleur', nom: b.nom, controls, emailId: `bsd-bemail-${i}`, emailVal: b.email, emailHidden: !(signe && dist), placeholder: 'email du gérant (signature à distance)', extra: (extra || '') + _bsdTelHtml('b', i, b.tel || '', signe && dist), off: !signe });
  }).join('');
  const bSection = bSigners.length
    ? bRows
    : `<div class="bsd-signer-row bsd-off"><div class="bsd-ord bsd-local">✓</div><div class="bsd-av" style="background:var(--pur,#7c3aed)">${escHtml(_bsdInitials(entLabel))}</div><div><div class="bsd-signer-meta"><span class="bsd-role">Bailleur · ${escHtml(entLabel)}</span><span class="bsd-sub">signé dans l'app</span></div><div class="bsd-sub" style="font-size:11px;color:var(--grn)">${_uiIcon('check', 13)} Signature bailleur in-app — pas d'envoi distant (mandataire)</div></div></div>`;

  const rows = locs.map((l, i) => {
    const nom = (l && l.nom) || ('Locataire ' + (i + 1));
    const email = (l && l.email) || '';
    const presentiel = !!(l && l.presentiel);
    const controls = _bsdModeSeg('l', i, presentiel ? 'pres' : 'dist', false);   // 🟢 Présentiel · 🟣 À distance
    return _bsdSignerRow({ rowId: `bsd-row-${i}`, ordTxt: i + 1, role: 'Locataire', nom, controls, emailId: `bsd-email-${i}`, emailVal: email, emailHidden: presentiel, extra: _bsdTelHtml('l', i, (bail.locataires && bail.locataires[i] && bail.locataires[i].tel) || '', !presentiel) });
  }).join('');

  const html = `
    <div class="ov" id="ov-send-b" onclick="closeBg(event,'ov-send-b')">
      <div class="modal" style="max-width:640px">
        <div class="m-head"><h3 id="bsd-title">${_uiIcon('sign')} Signer le bail — qui signe, et comment ?</h3><button class="m-close" onclick="closeM('ov-send-b')">✕</button></div>
        <div class="m-body">
          <div id="bsd-step1">
            <div class="bsd-banner bsd-banner-info">${_uiIcon('doc')} <div><b>Bail ${escHtml(_logLabel(ref))}</b> — ${escHtml(adresse)}.<br>Configurer qui signe : <b>présentiel</b> (dans l'app) ou <b>à distance</b> (lien par email). Chaque signataire distant reçoit son lien <b>à son tour</b> (partage manuel depuis la fiche).</div></div>
            <div class="bsd-state-label">${_uiIcon('building')} Côté bailleur · présentiel par défaut</div>
            ${bSection}
            <div class="bsd-state-label">${_uiIcon('key')} Côté locataires · distance par défaut</div>
            ${rows}
            <div id="bsd-visale"></div>
            <div id="bsd-ddt" class="bsd-ddt"></div>
            <div class="bsd-banner bsd-banner-info" style="margin-top:8px">${_uiIcon('bulb')} <div>Pour chaque signataire : <b><span style="color:var(--grn,#16a34a)">${_uiIcon('person', 13)}</span> Présentiel</b> = signe ici, dans l'app (chacun son tour) · <b><span style="color:var(--pur,#7c3aed)">${_uiIcon('send', 13)}</span> À distance</b> = reçoit un lien par email. Un co-gérant peut être mis sur <b><span style="color:#94a3b8">${_uiIcon('close', 13)}</span> Ne signe pas</b>.</div></div>
          </div>
        </div>
        <div class="m-foot">
          <button class="btn bs" onclick="closeM('ov-send-b')">Annuler</button>
          <button class="btn bp" id="bsd-next" onclick="_confirmBailSignatureFlow('${_lyQ(ref)}')">${_uiIcon('sign')}Lancer la signature</button>
        </div>
      </div>
    </div>`;
  const old = document.getElementById('ov-send-b'); if (old) old.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  openM('ov-send-b');
  _bsdVisaleInit(ref); // VISALE-GMBI : rappel non bloquant « activer le cautionnement avant de signer »
  _bsdDdtInit(ref);   // DDT annexé au bail — section « Pièces annexées » (vérifie les fichiers dès l'ouverture)
}

// VISALE-GMBI — rappel NON BLOQUANT dans « qui signe, et comment ? » : Visale refuse toute caution
// une fois le bail signé (« le contrat de cautionnement doit être validé avant la signature du bail »,
// visale.fr). Cocher la case l'enregistre sur le visa du bail et fait passer le bandeau au vert.
function _bsdVisaleInit(ref) {
  const host = el('bsd-visale'); if (!host) return;
  const bail = DB.baux[ref];
  const V = window.Visale;
  const vis = (bail && V) ? V.visaleNormaliser(bail.visale) : null;
  if (!vis) { host.innerHTML = ''; return; }
  const q = _lyQ(ref);
  host.innerHTML = vis.cautionValidee
    ? `<div class="bsd-banner bsd-banner-ok">${_uiIcon('check')} <div>Cautionnement Visale validé sur visale.fr (visa n° ${escHtml(vis.visaId)}).</div></div>`
    : `<div class="bsd-banner bsd-banner-warn">${_uiIcon('shield')} <div><b>Activer le cautionnement Visale avant de signer le bail.</b><br>
        Visale refuse toute caution une fois le bail signé. Valider le contrat de cautionnement sur l'espace bailleur visale.fr
        (visa n° ${escHtml(vis.visaId)}${vis.beneficiaires ? ', au nom de ' + escHtml(vis.beneficiaires) : ''}), puis cocher la case. Le bail peut être signé sans : c'est un rappel, pas un blocage.
        <div class="flex-c" style="gap:10px;flex-wrap:wrap;margin-top:8px">
          <a class="btn bs" href="https://www.visale.fr" target="_blank" rel="noopener">${_uiIcon('external')}Ouvrir visale.fr</a>
          <label class="flex-c visale-chk"><input type="checkbox" onchange="_bsdVisaleValider('${q}', this.checked)"> Cautionnement validé sur visale.fr</label>
        </div></div></div>`;
}
function _bsdVisaleValider(ref, on) {
  const bail = DB.baux[ref]; const V = window.Visale;
  if (!bail || !V) return;
  const vis = V.visaleNormaliser(bail.visale); if (!vis) return;
  vis.cautionValidee = !!on;
  bail.visale = vis;
  _stamp(bail);
  saveDB();
  _bsdVisaleInit(ref);
}

// FIL-ROUGE cleanup — _bsdSyncBailleurRow RETIRÉE : les bascules qu'elle synchronisait (bsd-bsign/
// bsd-bdist) sont remplacées par le sélecteur _bsdModeSeg/_bsdSetMode. Plus aucun appelant.


// CONTRAT-TYPE-2026-10 — les mentions « à compléter » du bail tel qu'il sera signé (même rendu que
// le PDF : buildBailStructure). Rien si le module n'est pas chargé ou si le rendu échoue : un
// avertissement ne doit jamais empêcher de signer.
function _bailMentionsACompleter(bail, log, ref) {
  try {
    const CT = (typeof window !== 'undefined') ? window.ContratType : null;
    if (!CT || typeof CT.mentionsACompleter !== 'function') return [];
    const ent = (DB.entites || []).find(e => e.nom === bail.entity) || {};
    const locs = bail.locataires || (bail.nom ? [{ nom: bail.nom, ddn: bail.ddn, lieuNaiss: bail.lieuNaiss }] : []);
    return CT.mentionsACompleter(buildBailStructure(bail, log, ref, ent, locs));
  } catch (e) { console.warn('[contrat-type] mentions à compléter', e); return []; }
}

// FIL-ROUGE — point d'entrée UNIQUE de la signature. Lit la matrice de présence de la modale
// ov-send-b, construit le plan (buildSignaturePlan), puis lance la
// signature présentielle CHACUN SON TOUR (popup + file _wizV2SoloSigner alignée sur les ids _SIGS :
// 'bailleur' mandataire / 'bailleur-<i>' co-gérant / 'loc-<i>' locataire), et relaie les distants après.
function _confirmBailSignatureFlow(ref) {
  const bail = DB.baux[ref];
  const log = DB.logements.find(l => l.ref === ref);
  if (!bail) { showToast('Bail introuvable', 'err'); return; }
  if (!(Array.isArray(bail.locataires) && bail.locataires.length)) {
    bail.locataires = [{ nom: bail.nom, email: bail.email }];
  }
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const signers = [];

  // Bailleur : mandataire (présentiel in-app forcé, v1) OU co-gérants (matrice modale, alignés getBailSignataires).
  const bSigners = _bailBailleurSigners(bail);       // [] si mandataire
  if (!bSigners.length) {
    const mandNom = (DB.params && DB.params.mandataire && DB.params.mandataire.nom) || bail.entity || 'Bailleur';
    signers.push({ id: window.BailSignataires.ID_MANDATAIRE, role: 'bailleur', nom: mandNom, mode: 'pres', email: '' });   /* S1 : id INDEXÉ, aligné §18 + paraphes */
  } else {
    for (let i = 0; i < bSigners.length; i++) {
      const modeEl = document.getElementById('bsd-mode-b-' + i);
      const emailEl = document.getElementById('bsd-bemail-' + i);
      const mode = (modeEl && modeEl.value) || bSigners[i].mode || 'pres';   // sélecteur explicite pres|dist|no
      const email = emailEl ? emailEl.value.trim() : (bSigners[i].email || '');
      if (mode === 'dist' && !emailRe.test(email)) {
        showToast('Email invalide pour ' + (bSigners[i].nom || ('Co-gérant ' + (i + 1))) + ' — à corriger, ou passer ce signataire en présentiel', 'err', 5000);
        if (emailEl) { emailEl.classList.add('err'); emailEl.focus(); } return;
      }
      const telEl = document.getElementById('bsd-tel-b-' + i);
      const tel = telEl ? telEl.value.trim() : (bSigners[i].tel || '');
      signers.push({ id: bSigners[i].id, role: 'bailleur', nom: bSigners[i].nom || ('Co-gérant ' + (i + 1)), mode, email, tel });   /* S1 : id du résolveur PARTAGÉ */
    }
  }

  // Locataires : matrice modale (présentiel toggle + email), alignés bail.locataires.
  const locs = _bsdLocataires(bail);
  for (let i = 0; i < locs.length; i++) {
    const modeEl = document.getElementById('bsd-mode-l-' + i);
    const emailEl = document.getElementById('bsd-email-' + i);
    const mode = (modeEl && modeEl.value) || 'dist';   // sélecteur explicite pres|dist (distance par défaut)
    const email = emailEl ? emailEl.value.trim() : ((locs[i] && locs[i].email) || '');
    if (mode === 'dist' && !emailRe.test(email)) {
      showToast('Email invalide pour ' + ((locs[i] && locs[i].nom) || ('Locataire ' + (i + 1))) + ' — à corriger, ou passer ce signataire en présentiel', 'err', 5000);
      if (emailEl) { emailEl.classList.add('err'); emailEl.focus(); } return;
    }
    const telEl = document.getElementById('bsd-tel-l-' + i);
    const tel = telEl ? telEl.value.trim() : ((locs[i] && locs[i].tel) || '');
    signers.push({ id: 'loc-' + i, role: 'locataire', nom: (locs[i] && locs[i].nom) || ('Locataire ' + (i + 1)), mode, email, tel });
  }

  // Plan (présentiels ordonnés bailleur→locataire + distants).
  const plan = window.BailSignPlan.buildSignaturePlan(signers);
  if (!plan.hasSigners) { showToast('Au moins un signataire requis', 'err', 5000); return; }
  if (!signers.some(s => s.role === 'bailleur' && s.mode !== 'no')) {
    showToast('Au moins un signataire côté bailleur est requis', 'err', 5000); return;   // garde légale
  }
  // Reprise : exclure les présentiels DÉJÀ signés (bail partiel rouvert) → pas de re-signature.
  const _already = (bail.signatures && bail.signatures.finales) || {};
  const pendingPres = plan.presentiels.filter(s => !_already[s.id]);
  if (!pendingPres.length && !plan.distants.length) {
    showToast('Ce bail est déjà signé', 'ok', 4000); if (typeof closeM === 'function') closeM('ov-send-b'); return;
  }
  // CONTRAT-TYPE-2026-10 — avertissement AU BAILLEUR SEUL (ici, dans son app : jamais dans le
  // document, jamais sur la page du locataire) si des mentions du bail restent « à compléter ».
  // Jamais bloquant : il décide. Pas sur une reprise (déjà signé en partie : texte figé).
  if (!Object.keys(_already).length && !_bailSigned(bail)) {
    const _manques = _bailMentionsACompleter(bail, log, ref);
    if (_manques.length && !confirm2(
      'Avant de lancer la signature — mentions du bail encore à compléter :\n\n'
      + _manques.map(m => '• ' + m.section + ' : ' + m.mention).join('\n')
      + '\n\nLe bail sera signé tel quel, avec « à compléter » à ces endroits.\n'
      + 'OK = signer quand même · Annuler = revenir compléter le bail.'
    )) return;
  }

  // DDT annexé au bail (art. 3-3) — plan FIGÉ sur le bail AVANT la génération : le §17 dit la réalité
  // et l'instantané signé le fige. Aucun blocage : seule une vérification de fichier encore en cours
  // fait patienter (window.open doit partir dans CE clic, on ne peut pas l'attendre ici).
  // Reprise d'un bail partiellement signé : plan FIGÉ (jamais recalculé sous une signature existante).
  try {
    if (!_ddtFrozen(bail)) {
      const _on = (_bsdDdt && _bsdDdt.ref === ref) ? _bsdDdt.on : {};
      const _enCours = _ddtAnnexRows(bail, log).rows.filter(r => r.statut === 'present' && _on[r.key] !== false
        && (!_ddtCheckCache[String(r.doc.id)] || _ddtCheckCache[String(r.doc.id)].st === 'pending'));
      if (_enCours.length) {
        // Attente BORNÉE (délai max de _ddtCheckPiece) ; une pièce jamais vérifiée (arrivée par synchro) est lancée ici.
        _enCours.forEach(r => { if (!_ddtCheckCache[String(r.doc.id)]) _ddtCheckPiece(r.doc).then(_bsdDdtRender); });
        showToast('Vérification des pièces jointes en cours (20 s max) — relancer dans un instant, ou décocher la pièce.', 'info', 5000);
        return;
      }
      const _ddt = _ddtBuildAnnexPlan(bail, log, _on);
      bail.annexesDdt = _ddt.plan;
      if (_ddt.dropped.length) showToast('Volume trop important : ' + _ddt.dropped.join(', ') + ' non joint(s) au PDF — noté au bail.', 'warn', 7000);
    }
  } catch (e) { console.warn('[DDT plan]', e); if (!_ddtFrozen(bail)) bail.annexesDdt = _ddtFallbackPlan(); }
  _bsdDdtSheetRemove();

  // Persiste les modes co-gérants (buildBailStructure/D2a) + le présentiel/email locataires (relais).
  if (bSigners.length) {
    bail.bailleurSign = signers.filter(s => s.role === 'bailleur')
      .map(s => s.mode === 'no' ? { mode: 'no' } : (s.mode === 'dist' ? { mode: 'dist', email: s.email, tel: s.tel || '' } : { mode: 'pres' }));
  }
  signers.filter(s => s.role === 'locataire').forEach((s, i) => {
    if (bail.locataires[i]) { bail.locataires[i].presentiel = (s.mode === 'pres'); if (s.mode === 'dist' && s.email) bail.locataires[i].email = s.email; if (s.mode === 'dist' && s.tel) bail.locataires[i].tel = s.tel; }
  });
  bail._modifiedAt = new Date().toISOString();
  saveDB();   // audit : saveBail() est le handler du FORMULAIRE d'édition (lit #b-ref) — ici on persiste la DB directement

  if (typeof closeM === 'function') closeM('ov-send-b');

  // Présentiels → popup de signature (chacun son tour). Si des distants restent, la popup est en mode
  // remote (ancres distants + stage) et le dernier genPDFNative émet la session relais via
  // _emitRemoteSignSession. Tous distants (aucun présentiel) → flux remote existant inchangé.
  if (pendingPres.length) {
    previewBailData(bail, log, ref, { signQueue: pendingPres.map(s => s.id), distants: plan.distants, remoteSign: plan.distants.length > 0 });
  } else {
    previewBailData(bail, log, ref, { remoteSign: true });
  }
}


// REFONTE-NAV Phase 2a — Sous-onglets de GROUPE : plusieurs pages sœurs présentées comme des
// sous-onglets sous un même parent. La barre est rendue en haut du contenu (#nav-subtabs-host) et
// pilote la navigation via go() (chaque sous-onglet = une page existante). Aucune page fusionnée :
// on réutilise les pages #p-<id> telles quelles + le routeur go(). En Phase 2a la sidebar garde ses
// 17 items (rien d'injoignable) ; en Phase 2b elle passera aux parents + zones.
const _NAV_GROUPS = [
  // KPI Lot 3 — « Tableau de bord » et « Suivi » supprimés (remplacés par l'écran Pilotage/#p-accueil
  // et l'onglet Loyers). Le groupe « Pilotage » perd son sous-menu ; « Accueil » reste seul.
  { parent: 'Locataires',          tabs: [['baux','Baux en cours'], ['candidats','Candidatures']] },
  { parent: 'Agenda',              tabs: [['agenda','Agenda'], ['equipements','Équipements']] },
  // D1 — la zone Argent tient en QUATRE entrées de plein droit : Mouvements · Loyers ·
  // Charges · Finances. Plus de groupe « Loyers & mouvements » (les deux pages n'étaient
  // pas de même nature) ni de groupe « Révisions » (l'IRL est absorbée par « Loyers » et sa
  // table est un réglage). Finances quitte le groupe Pilotage pour rejoindre l'Argent.
];
const _NAV_PAGE_GROUP = {};
_NAV_GROUPS.forEach(g => g.tabs.forEach(([id]) => { _NAV_PAGE_GROUP[id] = g; }));
// Page courante → id de l'item sidebar qui la « représente » (le parent = 1re page du groupe).
// Une page hors groupe se représente elle-même. Sert au surlignage du bon onglet parent.
function _navSidebarRep(page) {
  const g = _NAV_PAGE_GROUP[page];
  return g ? g.tabs[0][0] : page;
}
// Cible de CLIC d'un onglet parent = sa 1re page-enfant ENCORE affichée par le menu perso (le surlignage,
// lui, reste calé sur `_navSidebarRep` = 1re page canonique du groupe, via l'attribut data-nav). Évite
// d'atterrir sur un enfant masqué (audit : preset « Comptable » → clic Pilotage ouvrait Tableau de bord OFF).
function _navSidebarLanding(id, on) {
  const g = _NAV_PAGE_GROUP[id];
  if (!g) return id;
  const first = g.tabs.find(([pid]) => on.has(pid));
  return first ? first[0] : g.tabs[0][0];
}
// REFONTE-NAV Phase 4 — Menu PERSONNALISABLE (par compte, localStorage `_lsKey`). Chaque page-feuille
// on/off ; Accueil + Logements toujours ON (menu jamais vide). Filtre sidebar + feuille Plus +
// sous-onglets. Une page masquée reste joignable en `#p-<id>` (on masque du menu, on ne supprime pas).
// D1 — 13 entrées au lieu de 14 : « Loyer (IRL) » disparaît, absorbée par « Loyers ».
const _MENU_ALL = ['accueil','biens','baux','candidats','edl','agenda','equipements','mouvements','loyers','regul','finances'];
const _MENU_LOCKED = ['accueil','biens'];
const _MENU_LABELS = { accueil:'Accueil', finances:'Finances', biens:'Logements', baux:'Locataires', candidats:'Candidatures', edl:'États des lieux', agenda:'Agenda', equipements:'Équipements', mouvements:'Mouvements', loyers:'Loyers', regul:'Charges' };
const _MENU_ZONES = [
  { z:'Pilotage', ids:['accueil'] },
  { z:'Gestion locative', ids:['biens','baux','candidats','edl','agenda','equipements'] },
  { z:'Argent', ids:['mouvements','loyers','regul','finances'] },
];
const _MENU_PRESETS = {
  'Propriétaire — tout': _MENU_ALL.slice(),
  'Gestion locative': ['accueil','biens','baux','candidats','edl','agenda','equipements','mouvements','loyers'],
  'Comptable': ['accueil','biens','mouvements','loyers','finances','regul'],
};
function _menuKey() { return (typeof _lsKey === 'function') ? _lsKey('immo_menu_on') : 'immo_menu_on'; }
function _menuGetOn() {
  try {
    const raw = localStorage.getItem(_menuKey());
    if (raw) {
      const a = JSON.parse(raw);
      if (Array.isArray(a)) {
        // CDC-QUITTANCES-IRL étape 8 — MIGRATION des préférences enregistrées avant le
        // renommage des identifiants de page (loyers→mouvements, quittances→loyers, irl
        // retiré). Sans elle, les anciens identifiants seraient simplement filtrés par
        // `_MENU_ALL` et l'utilisateur verrait des entrées disparaître de son menu sans
        // comprendre pourquoi. Pure, idempotente, testée (js/core/nav-submenu.js).
        const migre = (typeof window !== 'undefined' && typeof window.migrerIdsMenuLoyers === 'function')
          ? window.migrerIdsMenuLoyers(a) : a;
        const s = new Set(migre.filter(x => _MENU_ALL.includes(x)));
        _MENU_LOCKED.forEach(x => s.add(x));
        // Ré-écriture une fois pour toutes : la prochaine lecture n'a plus rien à migrer.
        if (migre.length !== a.length || migre.some((x, i) => x !== a[i])) {
          try { localStorage.setItem(_menuKey(), JSON.stringify([...s])); } catch (e) {}
        }
        return s;
      }
    }
  } catch (e) {}
  return new Set(_MENU_ALL);   // défaut : tout affiché
}
function _menuSetOn(set) { try { localStorage.setItem(_menuKey(), JSON.stringify([...set])); } catch (e) {} }
// Un item sidebar/Plus (parent) est visible si AU MOINS une page de son groupe est ON (sinon lui-même).
function _menuItemVisible(id, on) {
  const g = _NAV_PAGE_GROUP[id];
  return g ? g.tabs.some(([pid]) => on.has(pid)) : on.has(id);
}
// HTML de la barre de sous-onglets pour la page courante (vide si la page n'appartient à aucun groupe).
// Réutilise le style d'onglets existant (.tabs/.tab) → cohérence visuelle, zéro CSS neuf.
function _navSubtabsHtml(page) {
  const g = _NAV_PAGE_GROUP[page];
  if (!g) return '';
  const on = _menuGetOn();   // Phase 4 — masque les sous-parties désactivées (garde la page courante)
  const tabs = g.tabs.filter(([id]) => on.has(id) || id === page);
  if (tabs.length < 2) return '';
  return '<div class="tabs nav-subtabs">' + tabs.map(([id, lb]) =>
    '<div class="tab' + (id === page ? ' act' : '') + '" onclick="go(\'' + id + '\')">' + lb + '</div>'
  ).join('') + '</div>';
}

function go(page, elNav) {
  // CDC-QUITTANCES-IRL D1/D2/D20 — ALIAS des anciens identifiants de page. Un `#p-quittances`
  // en favori, un lien enregistré, une entrée d'historique du navigateur : tout doit continuer
  // d'aboutir. `quittances` désignait l'ancien onglet des quittances émises, absorbé par
  // « Loyers » ; la page « Loyer (IRL) » n'existe plus (sa table est un réglage).
  if(page === 'quittances') return go('loyers', elNav);
  // `irl` désignait l'onglet des RÉVISIONS : il est absorbé par « Loyers ». (Sa table
  // d'indices, elle, est un réglage et vit dans Paramètres — on ne renvoie personne là-bas
  // depuis une alerte de révision.)
  if(page === 'irl') return go('loyers', elNav);
  // v14.3 PATRIMOINE-NAV-UNIFY : 'bailleurs' alias du hub Biens (mode bailleurs)
  if(page === 'bailleurs') {
    _biensViewMode = 'bailleurs';
    try { localStorage.setItem(_lsKey('immotrack_biens_view'), 'bailleurs'); } catch(e){}
    return go('biens', elNav);
  }
  // LOG-CANDIDATS : toute navigation annule une conversion candidat en attente. Si l'utilisateur
  // quitte le wizard bail par la sidebar (sans enregistrer ni fermer), le flag ne doit jamais être
  // consommé par un futur enregistrement de bail sans rapport. saveBail() ne navigue pas avant de
  // consommer le flag, donc ce reset n'interfère pas avec la conversion légitime.
  _pendingCandidatConv = null;
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('act'));
  // v15.38 : .v4s-a ajouté (sidebar V4) en plus de .ni (sidebar legacy)
  document.querySelectorAll('.ni, .v4s-a').forEach(n=>n.classList.remove('act'));
  const pg = el('p-'+page);
  if(pg) pg.classList.add('act');
  // v15.408 (audit mineur) — navigation sans elNav (retour/avant navigateur, appels programmatiques) :
  // retrouver l'item sidebar par attribut, sinon aucun onglet ne reste surligné après un back.
  // REFONTE-NAV Phase 2b — navigation programmatique / sous-onglet / retour navigateur : surligner
  // le PARENT sidebar qui représente la page (ex. go('finances') sans elNav → onglet « Pilotage »).
  if(!elNav) {
    const _rep = (typeof _navSidebarRep === 'function') ? _navSidebarRep(page) : page;
    // Sidebar V4 (active en prod) EN PREMIER via le parent représentant ; la legacy .ni (morte,
    // cachée) en repli seulement. Sinon un data-module legacy identique (ex. candidats/biens)
    // captait le surlignage sur un item invisible → parent V4 jamais allumé au clic d'un sous-onglet.
    // Match sur data-nav (clé CANONIQUE du parent) et non l'onclick : depuis le fix « landing »,
    // l'onclick vise la 1re page ENCORE activée (≠ page canonique) → un match onclick raterait.
    elNav = document.querySelector('.v4s-a[data-nav="' + _rep + '"]')
      || document.querySelector('.ni[data-module="' + page + '"]');
  }
  if(elNav) elNav.classList.add('act');
  currentPage = page;
  // v15.408 NAV-HISTORY-BACK — chaque page entre dans l'historique navigateur (#p-xxx) pour
  // que le bouton retour ramène à la page précédente au lieu de sortir de l'app. Les fiches
  // 360 poussent déjà leur propre hash (#log-fiche-… etc.) dans openLogFiche & co → exclues.
  // _navFromHash : posé par le handler hashchange (back/forward) pour ne pas RE-pousser.
  if (!window._navFromHash && page !== 'log-fiche' && page !== 'imm-fiche' && page !== 'ent-fiche') {
    try {
      const target = '#p-' + page;
      if (location.hash !== target) {
        if (window._navHashInit) history.pushState(null, '', target);
        else history.replaceState(null, '', target); // 1re navigation (boot) : pas d'entrée fantôme
      }
      window._navHashInit = true;
    } catch(e){}
  }
  // Update title
  const titles = {accueil:'Accueil',import:'Import de données',mouvements:'Mouvements',loyers:'Loyers',
    agenda:'Agenda',equipements:'Équipements & Entretiens',
    baux:'Locataires',candidats:'Candidats',regul:'Régularisation charges',
    edl:'États des lieux',
    emails:'📧 Communications',          // v15.79 EMAIL-ONGLET-PERMANENT (Sprint 19B)
    biens:'Biens',bailleurs:'Bailleurs', // v14.2 NAV-RESTRUCTURE
    finances:'Finances',                 // v15.265 REPORTING-BAILLEUR
    'log-fiche':'Fiche bien',            // v14.2 LOG-FICHE-360
    'imm-fiche':'Fiche immeuble',        // v14.3 IMM-FICHE-360
    'ent-fiche':'Fiche bailleur',        // v14.8 ENT-FICHE-360
    params:'Paramètres',export:'Export / Sauvegarde'};
  el('tb-title').textContent = titles[page]||page;
  // MOBILE-REFONTE — logo en tête PAR PAGE (retour Didier) : Accueil = marque + « Propryo »
  // (pas le mot « Accueil ») ; toutes les autres pages = marque + nom de la page (pas « Propryo »).
  // Bascule par la classe .tb-home sur la barre du haut (CSS ne montre le wordmark qu'en home).
  try { const _tb = document.querySelector('.tb'); if (_tb) _tb.classList.toggle('tb-home', page === 'accueil'); } catch(e){}
  try { _updatePerimChip(); } catch(e){}
  // REFONTE-NAV Phase 2a — barre de sous-onglets de groupe (Locataires→Baux/Candidatures, etc.)
  try { const _st = el('nav-subtabs-host'); if (_st) _st.innerHTML = _navSubtabsHtml(page); } catch(e){}
  // NAV-SOUS-MENUS (chantier A) — ouvre le groupe visité + re-rend la sidebar (enfant actif, chevrons).
  try { if (typeof _navSyncSubmenu === 'function') _navSyncSubmenu(page); } catch(e){}
  el('tb-actions').innerHTML = '';
  // v15.73 — Re-injecter les thèmes (présents sur TOUTES les pages V4)
  // + mode/période selon contexte (dashboard/accueil uniquement).
  try { if (typeof _v4SyncTopbarFilters === 'function') _v4SyncTopbarFilters(); } catch(e){}
  // v15.73 — Sync active state du bottom nav mobile (uniquement les 4 onglets directs)
  try {
    // Surlignage bottom-nav sur le PARENT représentant (comme la sidebar) : go('finances')/go('candidats')
    // → allume « Pilotage »/« Locataires », pas rien. (_rep de la sidebar est scopé au bloc !elNav → on
    // recalcule ici.)
    const _brep = (typeof _navSidebarRep === 'function') ? _navSidebarRep(page) : page;
    document.querySelectorAll('.v4-bnav .v4-bn').forEach(b => {
      b.classList.toggle('act', b.dataset.page === _brep);
    });
  } catch(e){}
  // Close mobile sidebar (+ backdrop overlay)
  if(window.innerWidth<=768) { el('sb')?.classList.remove('open'); el('sb-backdrop')?.classList.remove('open'); }
  // Render page
  const renders = {
    accueil:rAccueil, // v15.73 — page d'entrée par défaut (l'écran Pilotage)
    import:()=>{}, mouvements:()=>{initFilters();rMv();},
    agenda:()=>{initAgendaFilters();rAgenda();},
    equipements:()=>{initFilters();rEquipements();},
    baux:()=>{initFilters();const bauxActifTab=document.querySelector('#p-baux .tab.act');if(!bauxActifTab){const t=document.querySelector('#p-baux .tab');if(t)t.classList.add('act');}el('baux-tab-actifs').style.display='';el('baux-tab-historique').style.display='none';rBaux();}, candidats:()=>{ _candidatsTab = _candidatsTab || 'actifs'; rCandidats(); _autoPullCandidatures('open'); try{ _purgeCandidatsRefusesProd({ throttle:true }).catch(()=>{}); }catch(e){} },

    regul:()=>{initFilters();rRegulInit();},
    finances:()=>{ if (typeof rFinances === 'function') rFinances(); }, // v15.265 REPORTING-BAILLEUR
    loyers:()=>{initFilters();rLoyers();},   // CDC-QUITTANCES-IRL D1 : l'onglet « Loyers »
    emails:()=>{ if (typeof rEmailsPage === 'function') rEmailsPage(); }, // v15.79 EMAIL-ONGLET-PERMANENT
    edl:()=>{initFilters();rEDLList();},
    biens:rBiens,         // v14.2 NAV-RESTRUCTURE
    bailleurs:rBailleurs, // v14.2 NAV-RESTRUCTURE
    'log-fiche':rLogFiche,// v14.2 LOG-FICHE-360
    'imm-fiche':rImmFiche,// v14.3 IMM-FICHE-360
    'ent-fiche':rEntFiche,// v14.8 ENT-FICHE-360
    params:rParams,
    export:rExport,
  };
  if(renders[page]) renders[page]();
  try{ _renderInboxSurfaces(); }catch(e){}
  // MOBILE-REFONTE — toute navigation remonte le contenu en HAUT (retour Didier : ouvrir un
  // bien depuis une liste défilée l'affichait à la position de scroll, pas en haut). Le
  // conteneur défilant est #pc ; window en repli.
  try { const _pc = el('pc'); if (_pc) _pc.scrollTop = 0; if (window.scrollTo) window.scrollTo(0,0); } catch(e){}
}

// v15.140 BUG-MOBILE-MENU-PLUS — Ouverture/fermeture de la sidebar en overlay mobile.
// Avant : toggleSb() basculait juste la classe .open sur #sb (le bouton "Plus" en bottom
// nav semblait ne rien faire car aucun backdrop ne matérialisait l'overlay). Désormais on
// gère aussi le backdrop + on garantit que la sidebar V4 est peuplée avant ouverture.
function _openMobileMenu() {
  const sb = el('sb');
  if (!sb) return;
  // S'assurer que la sidebar V4 est peuplée (sinon overlay vide → effet "rien ne se passe")
  try {
    const v4 = el('v4s-sb-content');
    const isV4 = (typeof DB !== 'undefined' && DB.params && DB.params.dashRenderV === 'v2');
    if (isV4 && v4 && !v4.innerHTML.trim() && typeof _renderSidebarV4 === 'function') _renderSidebarV4();
  } catch(e){}
  sb.classList.add('open');
  el('sb-backdrop')?.classList.add('open');
  document.querySelector('.v4-bnav .v4-bn[data-page="params"]')?.classList.add('act');
}
function _closeMobileMenu() {
  el('sb')?.classList.remove('open');
  el('sb-backdrop')?.classList.remove('open');
}
function toggleSb() {
  // v15.142 — Sur mobile, le menu passe désormais par le bottom-sheet (#more-ov) : l'overlay
  // sidebar latérale ne s'affichait pas sur iOS (ombrage gris sans sidebar). Le burger du
  // haut ET le bouton "Plus" du bas ouvrent donc le même drawer fiable. Desktop/tablette :
  // la sidebar est statique, le burger n'est pas affiché (≥768px) → ce chemin n'y est pas pris.
  if (window.innerWidth <= 768) { _openMoreSheet(); return; }
  const sb = el('sb');
  if (!sb) return;
  if (sb.classList.contains('open')) _closeMobileMenu();
  else _openMobileMenu();
}

// v15.142 BUG-MOBILE-MENU-PLUS — Drawer bottom-sheet mobile. Remplace l'overlay sidebar
// latérale (qui échouait sur iPhone : ombrage gris sans sidebar visible). Le bottom-sheet
// est un élément dédié (#more-ov) en position:fixed bottom, sans dépendance à la sidebar.
function _openMoreSheet() {
  const ov = el('more-ov');
  if (!ov) return;
  try { if (typeof _renderMoreSheet === 'function') _renderMoreSheet(); } catch(e) { console.warn('[nav] more sheet', e); }
  ov.classList.add('open');
  document.querySelector('.v4-bnav .v4-bn[data-page="more"]')?.classList.add('act');
  document.body.style.overflow = 'hidden'; // empêche le scroll de l'arrière-plan
}
function _closeMoreSheet(e) {
  // Si appelé via clic sur l'overlay : ne fermer que si on a cliqué le fond (pas la feuille)
  if (e && e.target && e.target.id !== 'more-ov') return;
  const ov = el('more-ov');
  if (!ov) return;
  ov.classList.remove('open');
  document.querySelector('.v4-bnav .v4-bn[data-page="more"]')?.classList.remove('act');
  document.body.style.overflow = '';
}
function _moreGo(page) {
  _closeMoreSheet();
  if (typeof go === 'function') go(page);
}
// REFONTE-NAV Phase 3 — feuille « Plus » (mobile) générée depuis la source unique _V4_NAV_MODEL
// + les sous-parties (_NAV_GROUPS) → TOUT est joignable sur téléphone (fini le bug « Candidats/
// Finances introuvables »). Rendue à chaque ouverture (reflétera le menu perso en Phase 4).
function _renderMoreSheet() {
  const host = (typeof el === 'function') ? el('more-grid') : document.getElementById('more-grid');
  if (!host) return;
  const cu = (typeof countUnreadCandidats === 'function' && typeof DB !== 'undefined') ? countUnreadCandidats(DB.candidats || []) : 0;
  const item = (id, lb, ic, extra) => '<button type="button" class="more-it" onclick="_moreGo(\'' + id + '\')"><span class="more-ic">' + (ic || '') + '</span><span>' + lb + (extra || '') + '</span></button>';
  const on = _menuGetOn();   // Phase 4 — filtre du menu perso
  // BARRE À FAVORIS — 1re ligne corail : ouvre le picker plein écran (M-16).
  let html = '<button type="button" class="more-it more-customize" onclick="_closeMoreSheet();_openFavPicker()">'
    + '<span class="more-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" width="20" height="20"><circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/></svg></span>'
    + '<span>Personnaliser ma barre</span>'
    + '<svg class="more-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" width="15" height="15" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button>';
  // PREMIERS-PAS (retour Didier 16/10) : en tête de la feuille, visible sans défiler — la liste des étapes et la visite.
  html += '<button type="button" class="more-it" data-pp-entree="1" onclick="_closeMoreSheet();if(window.PremiersPas)window.PremiersPas.liste()"><span class="more-ic">' + _V4_NAV_ICONS.premiersPas + '</span><span>Premiers pas</span></button>';
  let pendingZone = null;
  _V4_NAV_MODEL.forEach(m => {
    if (m.h6) { pendingZone = m.h6; return; }
    if (!_menuItemVisible(m.id, on)) return;
    if (pendingZone) { html += '<div class="more-zone">' + pendingZone + '</div>'; pendingZone = null; }
    const candBadge = m.candBadge ? ' <span class="more-badge" id="more-candidats-badge"' + (cu > 0 ? '' : ' style="display:none"') + '>' + (cu || '') + '</span>' : '';
    html += item(m.id, m.lb, _V4_NAV_ICONS[m.ic], candBadge);
    // NAV APLATIE — plus de sous-chips « more-subs » : chaque entrée est un lien
    // simple. Les pages-enfants (Candidatures, Équipements) restent joignables via
    // la barre de sous-onglets en haut de leur page-groupe (_navSubtabsHtml).
  });
  // Réglages : sur desktop c'est le menu compte ; sur mobile on les expose ici pour rester joignables.
  html += '<div class="more-zone">Réglages</div>'
    + item('params', 'Paramètres', _V4_NAV_ICONS.params)
    + item('import', 'Import de données', _V4_NAV_ICONS.import)
    + item('export', 'Sauvegarde &amp; export', _V4_NAV_ICONS.export);
  host.innerHTML = html;
}

// ─── BARRE DU BAS À FAVORIS (téléphone) ─────────────────────────────────────
// Modèle EXACT de la maquette validée mockups/MOBILE-UX/NAV-FAVORIS-PROTO.html :
// `fav` = tableau ordonné de max 4 ids, Accueil verrouillé toujours en 1er.
// Chaque favori est soit un ONGLET (icône + label → go(page)), soit une ACTION
// RAPIDE (pastille corail « + label » → fonction existante de l'app). « Plus »
// reste toujours en dernier (ouvre la feuille + le picker « Personnaliser »).
// Persistance PAR COMPTE via _lsKey (comme le menu perso). DRY : les onglets
// appellent go() et les actions réutilisent les fonctions existantes — rien de
// réinventé. Icônes = line-icons currentColor (paths repris de la maquette).
const _FAV_MAX = 4;
const _FAV_ICONS = {
  accueil:'<path d="M4 11l8-7 8 7v8a1 1 0 01-1 1h-4v-6h-6v6H5a1 1 0 01-1-1z"/>',
  parc:'<path d="M4 21V8l8-5 8 5v13"/><path d="M9 21v-6h6v6"/>',
  loc:'<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3 3-5 6-5s6 2 6 5"/>',
  loyers:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  argent:'<path d="M3 7h18M3 12h18M3 17h10"/>',
  mvt:'<path d="M4 17l5-5 4 4 7-8"/>',
  charges:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',
  finances:'<path d="M4 19h16M6 16l4-6 3 3 5-7"/>',
  edl:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h3"/>',
  agenda:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M4 9h16M9 3v4M15 3v4"/>',
  addedl:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M12 9v6M9 12h6"/>',
  quit:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h4"/>',
  depense:'<rect x="3" y="6" width="18" height="12" rx="2"/><circle cx="12" cy="12" r="2.4"/><path d="M6.5 12h.01M17.5 12h.01"/>',
  candidat:'<circle cx="9.5" cy="8" r="3.2"/><path d="M4 20c0-3.3 2.5-5.5 5.5-5.5"/><path d="M18 8.5v6M15 11.5h6"/>',
  photo:'<rect x="3" y="7" width="18" height="13" rx="2"/><circle cx="12" cy="13.5" r="3.4"/><path d="M8.5 7l1.3-2h4.4L15.5 7"/>',
  rappel:'<path d="M6 9a6 6 0 0112 0c0 5 2 6 2 6H4s2-1 2-6z"/><path d="M10 20a2 2 0 004 0"/>'
};
// ONGLETS (10) — chaque `page` est un slug RÉEL vérifié dans go()/_V4_NAV_MODEL.
// NB audit : la page « Locataires » est le slug 'baux' (#p-baux), pas 'locataires' ;
// « Argent » n'a pas de page propre → son atterrissage est 'mouvements' (1re page de
// la zone Argent). 'argent' et 'mvt' pointent donc tous deux sur Mouvements.
const _FAV_TABS = [
  { id:'accueil',  nm:'Accueil',          sh:'Accueil',  ic:'accueil',  page:'accueil' },
  { id:'parc',     nm:'Parc',             sh:'Parc',     ic:'parc',     page:'biens' },
  { id:'loc',      nm:'Locataires',       sh:'Locat.',   ic:'loc',      page:'baux' },
  { id:'loyers',   nm:'Loyers',           sh:'Loyers',   ic:'loyers',   page:'loyers' },
  { id:'argent',   nm:'Argent',           sh:'Argent',   ic:'argent',   page:'mouvements' },
  { id:'mvt',      nm:'Mouvements',       sh:'Mouv.',    ic:'mvt',      page:'mouvements' },
  { id:'charges',  nm:'Charges',          sh:'Charges',  ic:'charges',  page:'regul' },
  { id:'finances', nm:'Finances',         sh:'Finances', ic:'finances', page:'finances' },
  { id:'edl',      nm:'États des lieux',  sh:'EDL',      ic:'edl',      page:'edl' },
  { id:'agenda',   nm:'Agenda',           sh:'Agenda',   ic:'agenda',   page:'agenda' },
];
// ACTIONS RAPIDES (6) — chaque `id` déclenche une fonction EXISTANTE (cf. _favRunAction).
const _FAV_ACTIONS = [
  { id:'addedl',   nm:'Faire un EDL',              sh:'EDL',       ic:'addedl',   action:true },
  { id:'depense',  nm:'Ajouter une dépense',       sh:'Dépense',   ic:'depense',  action:true },
  { id:'candidat', nm:'Ajouter un candidat',       sh:'Candidat',  ic:'candidat', action:true },
  { id:'photo',    nm:'Ajouter une photo / pièce', sh:'Photo',     ic:'photo',    action:true },
  { id:'rappel',   nm:'Ajouter un rappel',         sh:'Rappel',    ic:'rappel',   action:true },
  { id:'quit',     nm:'Faire une quittance',       sh:'Quittance', ic:'quit',     action:true },
];
const _FAV_ALL = _FAV_TABS.concat(_FAV_ACTIONS);
const _FAV_ALL_IDS = _FAV_ALL.map(x => x.id);
// Défaut intelligent (maquette) : Accueil (verrouillé) + Parc + Loyers + Faire un EDL.
const _FAV_DEFAULT = ['accueil', 'parc', 'loyers', 'addedl'];
function _favMeta(id) { return _FAV_ALL.find(x => x.id === id) || null; }
function _favKey() { return (typeof _lsKey === 'function') ? _lsKey('immo_fav_bar') : 'immo_fav_bar'; }
// Lecture normalisée : ids inconnus filtrés, unique, max 4. Accueil n'est PLUS forcé
// (retour Didier : c'est un favori comme les autres, on peut le retirer/remplacer).
function _favGet() {
  let arr = null;
  try { const raw = localStorage.getItem(_favKey()); if (raw) { const a = JSON.parse(raw); if (Array.isArray(a)) arr = a; } } catch (e) {}
  if (!arr) return _FAV_DEFAULT.slice();
  const out = [];
  arr.forEach(id => { if (_FAV_ALL_IDS.includes(id) && !out.includes(id) && out.length < _FAV_MAX) out.push(id); });
  return out;
}
function _favSet(list) {
  const out = [];
  (list || []).forEach(id => { if (_FAV_ALL_IDS.includes(id) && !out.includes(id) && out.length < _FAV_MAX) out.push(id); });
  try { localStorage.setItem(_favKey(), JSON.stringify(out)); } catch (e) {}
  return out;
}
function _favSvg(ic) { return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" width="20" height="20">' + (_FAV_ICONS[ic] || '') + '</svg>'; }
// Dispatch des actions rapides → fonctions EXISTANTES de l'app (DRY, aucune réinvention).
// 'photo' : l'app n'a pas de capture photo globale hors contexte (les photos vivent
// par logement / EDL / justificatif de mouvement) → on ouvre le hub Logements avec un
// repère vers l'onglet Photos de la fiche. Mapping le plus « souple », à confirmer.
function _favAddPhoto() {
  try { if (typeof go === 'function') go('biens'); } catch (e) {}
  try { if (typeof showToast === 'function') showToast('Ouvrir un logement puis l’onglet « Photos » de sa fiche pour ajouter des photos.', 'info', 4200); } catch (e) {}
}
const _FAV_ACTION_RUN = {
  addedl:   () => openNewEDL(),
  depense:  () => openNewMv(),
  candidat: () => openAddCandidat(),
  photo:    () => _favAddPhoto(),
  rappel:   () => openAgendaEvt(null),
  quit:     () => _openFaireQuittance(),
};
function _favRunAction(id) {
  try { if (typeof _closeMoreSheet === 'function') _closeMoreSheet(); } catch (e) {}
  const fn = _FAV_ACTION_RUN[id];
  if (!fn) return;
  try { fn(); }
  catch (e) { console.warn('[fav] action ' + id, e); try { if (typeof showToast === 'function') showToast('Action indisponible', 'err'); } catch (_) {} }
}
// La bottom-nav rend les favoris (onglet = icône+label ; action = pastille corail
// « + label ») + toujours « Plus ». Le surlignage .act (onglet actif) est câlé sur
// le PARENT représentant (_navSidebarRep) — recalculé aussi dans go() à chaque navig.
function _renderBottomNav() {
  const host = (typeof el === 'function') ? el('v4-bnav') : document.getElementById('v4-bnav');
  if (!host) return;
  const fav = _favGet();
  const rep = (typeof _navSidebarRep === 'function' && typeof currentPage !== 'undefined') ? _navSidebarRep(currentPage) : null;
  let html = fav.map(id => {
    const it = _favMeta(id); if (!it) return '';
    if (it.action) {
      return '<button type="button" class="v4-bn fav-act" data-page="fav:' + id + '" onclick="_favRunAction(\'' + id + '\')">'
        + '<span class="ic fav-ring">' + _favSvg(it.ic) + '</span>'
        + '<span class="lbl fav-albl">+ ' + (it.sh || it.nm) + '</span></button>';
    }
    const isAct = (it.page === rep);
    return '<button type="button" class="v4-bn' + (isAct ? ' act' : '') + '" data-page="' + it.page + '" onclick="go(\'' + it.page + '\')">'
      + '<span class="ic">' + _favSvg(it.ic) + '</span>'
      + '<span class="lbl">' + (it.sh || it.nm) + '</span></button>';
  }).join('');
  html += '<button type="button" class="v4-bn' + (rep === 'more' ? ' act' : '') + '" data-page="more" onclick="_openMoreSheet()"><span class="ic"><svg viewBox="0 0 24 24" fill="none" width="19" height="19"><circle cx="6" cy="12" r="1.5" fill="currentColor"/><circle cx="12" cy="12" r="1.5" fill="currentColor"/><circle cx="18" cy="12" r="1.5" fill="currentColor"/></svg></span><span class="lbl">Plus</span></button>';
  host.innerHTML = html;
  // La réécriture innerHTML efface le badge « candidats non lus » posé sur « Plus » par _renderInboxSurfaces
  // → on le re-pose (null-safe, ne re-render pas la sidebar). Sinon il disparaît après un toggle thème / menu / entité.
  try { if (typeof _renderInboxSurfaces === 'function') _renderInboxSurfaces(); } catch(e){}
}
// ─── PICKER « Personnaliser ma barre » (plein écran téléphone, M-16) ─────────
function _favPickerRow(it, fav) {
  const sel = fav.includes(it.id);
  const disabled = it.locked || (!sel && fav.length >= _FAV_MAX);
  const kind = it.locked ? 'Toujours présent' : (it.action ? 'Action rapide' : 'Onglet');
  const cls = ['fp-opt', it.action ? 'action' : '', sel ? 'sel' : '', disabled ? 'disabled' : ''].filter(Boolean).join(' ');
  return '<div class="' + cls + '"' + (it.locked ? '' : ' onclick="_favToggle(\'' + it.id + '\')"') + '>'
    + '<div class="fp-ic">' + _favSvg(it.ic) + '</div>'
    + '<div class="fp-lbl"><div class="fp-nm">' + it.nm + '</div><div class="fp-kind">' + kind + '</div></div>'
    + '<div class="fp-star"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12l5 5L20 6"/></svg></div>'
    + '</div>';
}
function _renderFavPicker() {
  const ov = document.getElementById('ov-fav-picker'); if (!ov) return;
  const body = ov.querySelector('.fp-body'); if (!body) return;
  const fav = _favGet();
  body.innerHTML = '<div class="fp-count">' + fav.length + ' / ' + _FAV_MAX + ' choisis</div>'
    + '<div class="fp-grp">Onglets</div>' + _FAV_TABS.map(it => _favPickerRow(it, fav)).join('')
    + '<div class="fp-grp">Actions rapides</div>' + _FAV_ACTIONS.map(it => _favPickerRow(it, fav)).join('');
}
function _openFavPicker() {
  let ov = document.getElementById('ov-fav-picker');
  if (!ov) {
    ov = document.createElement('div'); ov.id = 'ov-fav-picker';
    ov.innerHTML = '<div class="fp-head"><button type="button" class="fp-back" onclick="_closeFavPicker()" aria-label="Retour"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 18l-6-6 6-6"/></svg></button><div class="fp-title">Personnaliser ma barre</div></div>'
      + '<div class="fp-sub">Choisir jusqu’à 4 raccourcis pour la barre du bas — des onglets <em>ou</em> des actions. « Plus » reste toujours là pour le reste. Accueil est toujours présent.</div>'
      + '<div class="fp-body"></div>';
    document.body.appendChild(ov);
  }
  _renderFavPicker();
  ov.classList.add('open');
  document.body.style.overflow = 'hidden';
}
function _closeFavPicker() {
  const ov = document.getElementById('ov-fav-picker'); if (ov) ov.classList.remove('open');
  document.body.style.overflow = '';
}
function _favToggle(id) {
  const it = _favMeta(id); if (!it || it.locked) return;
  let fav = _favGet();
  const i = fav.indexOf(id);
  if (i >= 0) { fav.splice(i, 1); }
  else { if (fav.length >= _FAV_MAX) return; fav.push(id); }
  _favSet(fav);
  _renderFavPicker();
  try { _renderBottomNav(); } catch (e) {}
}

// REFONTE-NAV Phase 4 — écran « Personnaliser le menu » (depuis le menu compte). Presets + interrupteurs
// par onglet/sous-partie. Applique en direct (persiste + re-rend sidebar/sous-onglets ; la feuille Plus
// se régénère à l'ouverture). Overlay créé à la volée dans <body>.
function _openMenuPerso() {
  if (typeof _closeAcctMenu === 'function') { try { _closeAcctMenu(); } catch(e){} }
  let ov = document.getElementById('ov-menu-perso');
  if (!ov) { ov = document.createElement('div'); ov.id = 'ov-menu-perso'; ov.onclick = e => { if (e.target === ov) _closeMenuPerso(); }; document.body.appendChild(ov); }
  _renderMenuPerso();
  ov.classList.add('open');
}
function _closeMenuPerso() { const ov = document.getElementById('ov-menu-perso'); if (ov) ov.classList.remove('open'); }
function _menuIsPreset(name) { const s = new Set(_MENU_PRESETS[name]); _MENU_LOCKED.forEach(x => s.add(x)); const on = _menuGetOn(); return s.size === on.size && [...s].every(x => on.has(x)); }
function _menuApplyPreset(name) { const s = new Set((_MENU_PRESETS[name] || []).filter(x => _MENU_ALL.includes(x))); _MENU_LOCKED.forEach(x => s.add(x)); _menuSetOn(s); _menuAfterChange(); }
function _menuToggle(id) { if (_MENU_LOCKED.includes(id) || !_MENU_ALL.includes(id)) return; const on = _menuGetOn(); on.has(id) ? on.delete(id) : on.add(id); _menuSetOn(on); _menuAfterChange(); }
function _menuAfterChange() {
  try { if (typeof _renderSidebarV4 === 'function') _renderSidebarV4(); } catch(e){}
  try { const st = (typeof el === 'function' ? el('nav-subtabs-host') : document.getElementById('nav-subtabs-host')); if (st && typeof currentPage !== 'undefined') st.innerHTML = _navSubtabsHtml(currentPage); } catch(e){}
  _renderMenuPerso();
}
function _renderMenuPerso() {
  const ov = document.getElementById('ov-menu-perso'); if (!ov) return;
  const esc = (typeof escHtml === 'function') ? escHtml : (s => String(s || ''));
  const on = _menuGetOn();
  const chips = Object.keys(_MENU_PRESETS).map(p => '<button class="mp-pre' + (_menuIsPreset(p) ? ' on' : '') + '" onclick="_menuApplyPreset(\'' + _lyQ(p) + '\')">' + esc(p) + '</button>').join('')
    + '<span class="mp-pre' + (Object.keys(_MENU_PRESETS).some(_menuIsPreset) ? '' : ' on') + '">Sur-mesure</span>';
  const zones = _MENU_ZONES.map(z => '<div class="mp-zone"><div class="mp-zt">' + esc(z.z) + '</div>' + z.ids.map(id => {
    const lk = _MENU_LOCKED.includes(id), isOn = on.has(id);
    return '<div class="mp-row"><span>' + esc(_MENU_LABELS[id]) + (lk ? '<span class="mp-lk">obligatoire</span>' : '') + '</span><span class="mp-sw' + (isOn ? ' on' : '') + '"' + (lk ? '' : ' onclick="_menuToggle(\'' + id + '\')"') + '><span class="mp-kn"></span></span></div>';
  }).join('') + '</div>').join('');
  ov.innerHTML = '<div class="mp-card" onclick="event.stopPropagation()">'
    + '<div class="mp-head"><b>Personnaliser mon menu</b><button class="mp-x" onclick="_closeMenuPerso()" aria-label="Fermer">✕</button></div>'
    + '<p class="mp-sub">Afficher seulement les onglets utilisés — propre au compte. Accueil et Logements restent toujours là. Un onglet masqué reste accessible par lien direct.</p>'
    + '<div class="mp-pre-row">' + chips + '</div>'
    + '<div class="mp-zones">' + zones + '</div>'
    + '</div>';
}

function toggleSbCollapse() {
  const sb = el('sb');
  if(!sb) return;
  sb.classList.toggle('sb-collapsed');
  try { localStorage.setItem(_lsKey('immotrack_sb_collapsed'), sb.classList.contains('sb-collapsed')?'1':'0'); } catch(e){}
}

// v15.22 Phase B — 2 modes : Sobre (clair) ↔ Dark (sombre).
// v15.reskin — colore supprimé ; cycle = sobre ↔ dark uniquement.
// v15.25 BUGFIX : clé localStorage 'immotrack_theme_mode' (séparée de 'immotrack_theme').
// Compatibilité descendante : 'light' → 'sobre', 'colore' → 'sobre'.
const _THEME_CYCLE = ['sobre', 'dark'];
const _THEME_LABELS = { sobre: '🌞', dark: '🌙' };
function _normalizeTheme(t) {
  if (t === 'light' || t === 'colore') return 'sobre';
  if (_THEME_CYCLE.includes(t)) return t;
  return 'dark'; // default
}
function toggleTheme() {
  const html = document.documentElement;
  const cur = _normalizeTheme(html.getAttribute('data-theme'));
  const next = cur === 'dark' ? 'sobre' : 'dark';
  html.setAttribute('data-theme', next);
  const btn = el('sb-theme-btn');
  if (btn) { btn.textContent = _THEME_LABELS[next]; btn.title = 'Thème : ' + next + ' (cliquer pour changer)'; }
  try { localStorage.setItem(_lsKey('immotrack_theme_mode'), next); } catch(e) {}
}

// v15.38 : toggleFontSize SUPPRIMÉE sur demande user (police bumpée systématiquement
// dans le design V4, plus besoin de switch user). Variable localStorage 'immotrack_fontsize'
// conservée pour compat descendante (lue dans _applyStoredPrefs si déjà set).

function _applyStoredPrefs() {
  try {
    // v15.22 Phase B — 3 thèmes, default 'dark'.
    // v15.25 BUGFIX : clé 'immotrack_theme_mode' (string sobre/colore/dark)
    // séparée de 'immotrack_theme' (objet JSON personnalisation CSS Paramètres).
    // Migration : si la nouvelle clé n'existe pas mais qu'il y a une vieille
    // valeur STRING dans 'immotrack_theme' (ancienne version), on la récupère.
    let raw = localStorage.getItem(_lsKey('immotrack_theme_mode'));
    if (!raw) {
      const legacy = localStorage.getItem(_lsKey('immotrack_theme'));
      if (legacy && !legacy.trim().startsWith('{')) {
        // C'est une string ('light'/'dark'/'sobre'/'colore'), on la migre
        raw = legacy;
        try { localStorage.setItem(_lsKey('immotrack_theme_mode'), _normalizeTheme(legacy)); } catch(e){}
      }
    }
    // v15.38 DASH-REFONTE-GLOBALE-V4 CP1 : si dashRenderV='v2' et aucune préf user explicite,
    // force le thème dark (cohérence sidebar/main, mockup V4 Stripe).
    // L'utilisateur garde la main via le bouton thème (qui set immotrack_theme_mode).
    if (!raw && typeof DB !== 'undefined' && DB.params && DB.params.dashRenderV === 'v2') {
      raw = 'dark';
      try { localStorage.setItem(_lsKey('immotrack_theme_mode'), 'dark'); } catch(e){}
    }
    raw = raw || 'dark';
    const theme = _normalizeTheme(raw);
    document.documentElement.setAttribute('data-theme', theme);
    const btn = el('sb-theme-btn');
    if (btn) { btn.textContent = _THEME_LABELS[theme]; btn.title = 'Thème : ' + theme + ' (cliquer pour changer)'; }

    // v15.38 : font-size (data-fontsize='lg') restauré pour users existants mais
    // bouton de toggle supprimé. Compat descendante uniquement.
    const fs = localStorage.getItem(_lsKey('immotrack_fontsize')) || '';
    if(fs === 'lg') document.documentElement.setAttribute('data-fontsize', 'lg');

    const collapsed = localStorage.getItem(_lsKey('immotrack_sb_collapsed')) === '1';
    if(collapsed) el('sb')?.classList.add('sb-collapsed');

    // v15.38 DASH-REFONTE-GLOBALE-V4 CP1 : restaure l'état plié des sections sidebar individuelles
    try {
      const rawSec = localStorage.getItem(_lsKey('immotrack_sb_sections_collapsed'));
      if (rawSec) {
        const arr = JSON.parse(rawSec);
        if (Array.isArray(arr)) {
          arr.forEach(id => {
            const sec = document.querySelector('.sb-section[data-module-section="' + id + '"]');
            if (sec) sec.classList.add('sb-section-collapsed');
          });
        }
      }
    } catch(e){}
  } catch(e){}
}

// v15.38 DASH-REFONTE-GLOBALE-V4 CP1 — Sidebar : plier/déplier une section individuellement.
function toggleSbSection(titleEl) {
  const section = titleEl && titleEl.closest ? titleEl.closest('.sb-section') : null;
  if (!section) return;
  section.classList.toggle('sb-section-collapsed');
  const id = section.getAttribute('data-module-section');
  if (!id) return;
  try {
    const raw = localStorage.getItem(_lsKey('immotrack_sb_sections_collapsed')) || '[]';
    const arr = JSON.parse(raw);
    const set = new Set(Array.isArray(arr) ? arr : []);
    if (section.classList.contains('sb-section-collapsed')) set.add(id);
    else set.delete(id);
    localStorage.setItem(_lsKey('immotrack_sb_sections_collapsed'), JSON.stringify([...set]));
  } catch(e){}
}

// v15.38 DASH-REFONTE-GLOBALE-V4 CP1 — Sidebar : entités épinglées top 3 par revenus annuels.
// Clic → navigue dashboard + filtre sur cette entité.
function _renderSidebarPinned() {
  const wrap = (typeof el === 'function') ? el('sb-pinned-ents') : null;
  if (!wrap) return;
  const renderV = (typeof DB !== 'undefined' && DB.params && DB.params.dashRenderV) || 'v1';
  if (renderV !== 'v2' || typeof DB === 'undefined' || !DB.entites) { wrap.innerHTML = ''; return; }
  const yr = String(new Date().getFullYear());
  const aliveFn = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  const aliveEnts = DB.entites.filter(aliveFn);
  const aliveLogs = (DB.logements || []).filter(aliveFn);
  const aliveMvs  = (DB.mouvements || []).filter(aliveFn);
  const scored = aliveEnts.map(e => {
    const eLogs = aliveLogs.filter(l => l.entity === e.nom);
    const eRefs = eLogs.map(l => l.ref);
    const eImms = [...new Set(eLogs.map(l => l.imm).filter(Boolean))];
    const eCr = aliveMvs.filter(m => {
      if (!m.date || !m.date.startsWith(yr)) return false;
      return eRefs.includes(m.qui) || eImms.includes(m.imm) || m.qui === 'SCI:' + e.nom;
    }).reduce((s, m) => s + (m.cr || 0), 0);
    return {nom: e.nom, cr: eCr};
  }).filter(x => x.cr > 0).sort((a, b) => b.cr - a.cr).slice(0, 3);

  if (scored.length === 0) { wrap.innerHTML = ''; return; }

  const fmtK = n => n >= 10000 ? Math.round(n / 1000) + ' k€' : Math.round(n) + ' €';
  const esc = (typeof escHtml === 'function') ? escHtml : (s => String(s||''));
  const escAttr = s => _lyQ(s);

  wrap.innerHTML = '<div class="sb-section-title sb-pinned-title">📌 Entités principales</div>'
    + scored.map(s =>
        '<div class="sb-pinned-ent" onclick="_sbPinnedClick(\'' + escAttr(s.nom) + '\')" role="button" tabindex="0" title="' + esc(s.nom) + ' — filtrer le dashboard">'
        + '<span class="sb-pinned-ic" aria-hidden="true">🏛</span>'
        + '<span class="sb-pinned-name">' + esc(s.nom) + '</span>'
        + '<span class="sb-pinned-rev">' + esc(fmtK(s.cr)) + '</span>'
        + '</div>'
      ).join('');
}

function _sbPinnedClick(name) {
  // KPI Lot 3 — le dashboard a disparu : on pose le filtre d'entité GLOBAL (source unique
  // _activeEntity) puis on ouvre l'écran Pilotage (#p-accueil), qui lit _finActiveEnt().
  if (typeof _setActiveEntity === 'function') _setActiveEntity(name);
  if (typeof go === 'function') go('accueil');
}

// v15.154 — Nom d'affichage de l'utilisateur (commercialisation : plus de « Didier » codé en dur).
// Priorité : prénom de salutation (Paramètres) → nom du bailleur → nom du compte Google connecté → ''.
// Les appelants gèrent le cas vide (salutation neutre sans nom).
function _appUserName() {
  try {
    // Cloud + partage : un utilisateur qui n'est PAS le propriétaire de l'espace chargé ne doit pas
    // hériter du nom du propriétaire (DB.params — userName/bailleur — est PARTAGÉ par-espace). On affiche
    // son identité auth (renseignée par supabase-entry.js). isOwner===false ⇒ invité scopé/membre tiers.
    const ci = (typeof window !== 'undefined') ? window.__immoCloudInfo : null;
    if (ci && ci.isOwner === false) return String(ci.displayName || ci.email || '').trim();
    const p = (typeof DB !== 'undefined' && DB.params) ? DB.params : null;
    if (p) {
      if (p.userName && String(p.userName).trim()) return String(p.userName).trim();
      if (p.bailleurNom && String(p.bailleurNom).trim()) return String(p.bailleurNom).trim();
    }
  } catch (e) {}
  return '';
}

// Comparateur de NOMS naturel : insensible casse/accents + numérique (« Apt 2 » AVANT « Apt 10 »,
// « Bât 9 » avant « Bât 10 »). Utilisé par tous les tris A→Z / Z→A des biens (#7 test partage).
function _natCmp(a, b) {
  return String(a == null ? '' : a).localeCompare(String(b == null ? '' : b), 'fr', { numeric: true, sensitivity: 'base' });
}

// ── B3 (RETOURS-2026-10-05) — NOM D'AFFICHAGE du logement : `log.libelle` est un TEXTE D'ÉCRAN, `log.ref` reste la clé.
// Toujours résolu PAR LA RÉFÉRENCE dans DB.logements : on ne lit JAMAIS `x.libelle` sur l'objet reçu (le ruban IRL, un
// mouvement, une ligne d'import portent un `libelle` qui n'est pas le nom du logement). Ref inconnue (« SCI:… », saisie libre,
// logement purgé) → la chaîne reçue, sans erreur. Texte NON échappé : escHtml à chaque site innerHTML ; jamais dans un
// attribut value/data-/onclick (qui gardent la référence). Voir docs/subjects/BAIL-EN-COURS-NOM-AFFICHAGE.md.
function _logFindParRef(x) {
  const brut = String((x && typeof x === 'object') ? (x.ref == null ? '' : x.ref) : (x == null ? '' : x));
  const ref = brut.split('@@')[0];
  // Multi-espace (audit B3 🟡6) : même réf dans deux espaces → on préfère le logement de l'espace demandé
  // (_espaceId de l'objet reçu, sinon suffixe « ref@@espaceId »), puis n'importe quel espace.
  const esp = (x && typeof x === 'object' && x._espaceId) ? x._espaceId : (brut.indexOf('@@') >= 0 ? brut.slice(brut.indexOf('@@') + 2) : '');
  const logs = (typeof DB !== 'undefined' && DB && Array.isArray(DB.logements)) ? DB.logements : [];
  const mem = z => z && z.ref === ref;
  return { ref: ref, log: (esp && logs.find(z => mem(z) && z._espaceId === esp && !z._deleted)) || logs.find(z => mem(z) && !z._deleted) || logs.find(mem) || null };
}
// Repli sans module LogLabel (script non chargé) : libellé simple, vide s'il est égal à la référence.
function _logNomRepli(log) {
  const n = String((log && log.libelle) || '').replace(/\s+/g, ' ').trim().slice(0, 60);
  return (n && n.toLowerCase() !== String(log.ref || '').toLowerCase()) ? n : '';
}
function _logLabel(x) {
  const r = _logFindParRef(x);
  if (!r.log) return r.ref;
  return (window.LogLabel && LogLabel.libelle) ? LogLabel.libelle(r.log) : _logNomRepli(r.log) || r.log.ref;
}
function _logLabelRef(x) {
  const r = _logFindParRef(x);
  if (!r.log) return r.ref;
  return (window.LogLabel && LogLabel.libelleEtRef) ? LogLabel.libelleEtRef(r.log) : (_logNomRepli(r.log) ? _logNomRepli(r.log) + ' · ' + r.log.ref : r.log.ref);
}
// Recherche (libellé OU ref) et tri (nom naturel puis ref) des logements.
function _logLabelMatch(log, q) { return (window.LogLabel && LogLabel.correspond) ? LogLabel.correspond(log, q) : (String((log && log.ref) || '') + ' ' + String((log && log.libelle) || '')).toLowerCase().includes(String(q || '').toLowerCase()); }
function _logLabelCmp(a, b) { return (window.LogLabel && LogLabel.comparer) ? LogLabel.comparer(a, b) : (_natCmp(_logNomRepli(a) || (a && a.ref), _logNomRepli(b) || (b && b.ref)) || _natCmp(a && a.ref, b && b.ref)); }

// v15.38 DASH-REFONTE-GLOBALE-V4 CP1 — Sidebar : footer utilisateur (avatar + nom + lien Paramètres).
function _renderSidebarUserFooter() {
  const wrap = (typeof el === 'function') ? el('sb-user-footer') : null;
  if (!wrap) return;
  const renderV = (typeof DB !== 'undefined' && DB.params && DB.params.dashRenderV) || 'v1';
  if (renderV !== 'v2') { wrap.innerHTML = ''; return; }
  const fullName = _appUserName();
  const parts = fullName.split(/\s+/).filter(Boolean);
  const initials = (parts.map(s => s[0]).slice(0, 2).join('') || '👤').toUpperCase();
  const shortName = parts.length >= 2 ? (parts[0] + ' ' + parts[1][0].toUpperCase() + '.') : (fullName || 'Mon compte');
  const esc = (typeof escHtml === 'function') ? escHtml : (s => String(s||''));
  wrap.innerHTML = '<div class="sb-user-avatar" aria-hidden="true">' + esc(initials) + '</div>'
    + '<div class="sb-user-info">'
    +   '<strong class="sb-user-name">' + esc(shortName) + '</strong>'
    +   '<button type="button" class="sb-user-link" onclick="go(\'params\')" aria-label="Aller aux Paramètres">Paramètres ›</button>'
    + '</div>';
}

// v15.38 DASH-REFONTE-GLOBALE-V4 CP1 — Init sidebar V4 (appelé après chargement DB).
function _initSidebarV2() {
  try { _renderSidebarPinned(); } catch(e){ console.warn('[sidebar pinned]', e); }
  try { _renderSidebarUserFooter(); } catch(e){ console.warn('[sidebar footer]', e); }
  // v15.38 : Active mode V4 Stripe sur <body> + render sidebar V4 + sync filtres topbar
  try { _setDashV4Mode(); _renderSidebarV4(); _v4SyncTopbarFilters(); _v4SyncBannersHeight(); } catch(e){ console.warn('[V4 init]', e); }
}

// v15.38 — Mesure la hauteur des bannières top (sandbox-banner + readonly-banner)
// et set --top-banners-h pour que .layout V4 prenne la hauteur restante (footer DK
// reste toujours visible quel que soit le nombre de bannières).
// Les bandeaux qui prennent de la hauteur EN TÊTE de page. Liste unique : elle
// était recopiée ici et dans le MutationObserver plus bas, et une seule des deux
// copies aurait été mise à jour (EDL TERRAIN lot 4 ajoute 'hl-bar', le bandeau
// hors ligne — sans quoi .layout garde 100vh et le bandeau recouvre l'app).
// 'pwa-invite' : l'invitation « Installer Propryo » (téléphone) entre elle aussi dans le flux en tête d'écran.
const _V4_TOP_BANNERS = ['sandbox-banner', 'readonly-banner', 'hl-bar', 'pwa-invite'];
function _v4SyncBannersHeight() {
  let h = 0;
  _V4_TOP_BANNERS.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    // Exclus si .hidden, display:none, ou class hidden (legacy)
    if (el.classList && el.classList.contains('hidden')) return;
    if (getComputedStyle(el).display === 'none') return;
    if (el.offsetHeight) h += el.offsetHeight;
  });
  document.documentElement.style.setProperty('--top-banners-h', h + 'px');
}
if (typeof window !== 'undefined') {
  window.addEventListener('resize', () => { try { _v4SyncBannersHeight(); } catch(e){} });
  // Re-mesure après l'init complète (readonly-banner peut être toggled tardivement)
  if (document.readyState !== 'loading') {
    setTimeout(() => { try { _v4SyncBannersHeight(); } catch(e){} }, 200);
  } else {
    document.addEventListener('DOMContentLoaded', () => {
      setTimeout(() => { try { _v4SyncBannersHeight(); } catch(e){} }, 200);
    });
  }
  // MutationObserver sur les class des bannières → recompute immédiatement
  setTimeout(() => {
    try {
      const obs = new MutationObserver(() => { _v4SyncBannersHeight(); });
      _V4_TOP_BANNERS.forEach(id => {
        const el = document.getElementById(id);
        if (el) obs.observe(el, {attributes: true, attributeFilter: ['class', 'style']});
      });
    } catch(e){}
  }, 500);
}

// v15.38 — Inject TOUS les contrôles topbar quand Dashboard V4 :
//   1. Sélecteur mode (Solo / Premium / Gestionnaire)
//   2. Filtres Année / Mois (miroirs synced avec #dash-year / #dash-mois)
//   3. Boutons thèmes (sobre / coloré / dark)
// v15.73 — Topbar V4 : THÈMES (sobre/coloré/dark) sur TOUTES les pages V4
// + mode (Solo/Premium/Gestionnaire) + période (année/mois) uniquement sur
// dashboard ET accueil (contextuels). User feedback : "les couleurs partout".
function _v4SyncTopbarFilters() {
  const isV4 = (typeof DB !== 'undefined' && DB.params && DB.params.dashRenderV === 'v2');
  const tbActions = (typeof el === 'function') ? el('tb-actions') : null;
  if (!tbActions) return;
  if (!isV4) {
    // Mode V1 legacy : on retire les contrôles V4 si présents
    const existing = tbActions.querySelector('.v4s-tb-controls');
    if (existing) existing.remove();
    return;
  }
  const onAccueil   = document.querySelector('#p-accueil.act') !== null;
  // KPI Lot 3 — le Tableau de bord (et son sélecteur de mode Premium/Gestionnaire) sont supprimés.
  // La barre de contexte ne porte plus que le filtre période (Année / Mois), sur l'écran Pilotage.
  const showPeriod  = false;   // Pilotage = état à l'instant T : sélecteur Année/Mois retiré.

  const curTheme = document.documentElement.getAttribute('data-theme') || 'dark';

  // Déjà injecté ? Sync seulement (état boutons + valeurs miroirs)
  const existing = tbActions.querySelector('.v4s-tb-controls');
  if (existing) {
    const hadPeriod = !!existing.querySelector('#v4s-tb-year');
    if (hadPeriod !== showPeriod) {
      // Le contexte a changé (on est passé de dashboard à autre page ou vice-versa)
      // → rebuild complet (plus simple que toggle dynamique)
      existing.remove();
    } else {
      // Sync valeurs
      const yrMirror = existing.querySelector('#v4s-tb-year');
      const moMirror = existing.querySelector('#v4s-tb-mois');
      const origYr = el('dash-year');
      const origMo = el('dash-mois');
      if (yrMirror && origYr) {
        if (yrMirror.options.length !== origYr.options.length) yrMirror.innerHTML = origYr.innerHTML;
        yrMirror.value = origYr.value;
      }
      if (moMirror && origMo) {
        if (moMirror.options.length !== origMo.options.length) moMirror.innerHTML = origMo.innerHTML;
        moMirror.value = origMo.value;
      }
      existing.querySelectorAll('.v4s-theme-btn').forEach(b => b.classList.toggle('act', b.dataset.theme === curTheme));
      return;
    }
  }

  // Build initial
  const themeBtn = (mode, icon, label) =>
    '<button type="button" class="v4s-theme-btn' + (curTheme === mode ? ' act' : '') + '" '
    + 'data-theme="' + mode + '" onclick="_v4SetTheme(\'' + mode + '\')" '
    + 'title="Thème ' + label + '" aria-label="Activer le thème ' + label + '"'
    + (curTheme === mode ? ' aria-pressed="true"' : '') + '>'
    + icon + '</button>';

  // Thèmes (toujours présents)
  const themesHtml =
      '<div class="v4s-theme-tb-row" role="group" aria-label="Sélecteur de thème">'
    +   themeBtn('sobre',  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.4 1.4M17.2 17.2 18.6 18.6M18.6 5.4 17.2 6.8M6.8 17.2 5.4 18.6" stroke-linecap="round"/></svg>', 'clair')
    +   themeBtn('dark',   '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.8A8.5 8.5 0 1 1 11.2 3a6.5 6.5 0 0 0 9.8 9.8Z" stroke-linejoin="round"/></svg>', 'sombre')
    + '</div>';

  // Contextuel : le filtre période (Année / Mois) sur l'écran Pilotage.
  let contextualHtml = '';
  if (showPeriod) {
    const origYr = el('dash-year');
    const origMo = el('dash-mois');
    const yrOptions = origYr ? origYr.innerHTML : '';
    const moOptions = origMo ? origMo.innerHTML : '';
    contextualHtml += ''
      + '<span class="v4s-tb-sep"></span>'
      + '<span class="v4s-tb-label">Année</span>'
      + '<select id="v4s-tb-year" autocomplete="off" name="v4s-tb-year-' + Date.now() + '" onchange="_v4OnTopbarFilterChange(\'year\',this.value)">' + yrOptions + '</select>'
      + '<select id="v4s-tb-mois" autocomplete="off" name="v4s-tb-mois-' + Date.now() + '" onchange="_v4OnTopbarFilterChange(\'mois\',this.value)">' + moOptions + '</select>';
  }

  const wrap = document.createElement('div');
  wrap.className = 'v4s-tb-controls';
  wrap.innerHTML = themesHtml + contextualHtml;
  tbActions.appendChild(wrap);

  if (showPeriod) {
    const origYr = el('dash-year');
    const origMo = el('dash-mois');
    const yrVal = origYr ? origYr.value : '';
    const moVal = origMo ? origMo.value : '';
    const yrSel = wrap.querySelector('#v4s-tb-year');
    const moSel = wrap.querySelector('#v4s-tb-mois');
    if (yrSel && yrVal) yrSel.value = yrVal;
    if (moSel) moSel.value = moVal;
  }
}


// KPI Lot 3 — `_DMF` (noms de mois) était défini dans le bloc du Tableau de bord (supprimé) mais
// reste utilisé par l'écran Pilotage (_renderPilotage) et par Finances (labels/tooltips de période).
// Rétabli ici comme constante top-level partagée.
const _DMF = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];

// Re-render de la page liée à la PÉRIODE affichée (barre Année/Mois partagée). KPI Lot 3 — le
// Tableau de bord a disparu : la seule page période/data à rafraîchir « après action » est
// l'écran Pilotage (#p-accueil). Sert aussi de cible de rebranchement des ex-appels _rPeriodPage().
function _rPeriodPage() {
  try {
    if (typeof currentPage !== 'undefined' && currentPage === 'accueil' && typeof rAccueil === 'function') { rAccueil(); return; }
  } catch (e) {}
}

// Relais change du miroir topbar → set valeur sur le select original + re-render de la page affichée.
function _v4OnTopbarFilterChange(which, value) {
  const origId = which === 'year' ? 'dash-year' : 'dash-mois';
  const orig = (typeof el === 'function') ? el(origId) : null;
  if (orig) {
    orig.value = value;
    // v15.38 — marque comme "user pick" pour ne plus écraser avec mois courant
    orig.dataset.userPicked = '1';
    _rPeriodPage();
  }
}

