// ═══════════════════════════════════════════════════════════════════
// BAIL WIZARD — étape 3 phase 2 v12.44 / v15.249 B7 (D-B13) : 4→3 étapes
// 3 étapes : 1=Personnes, 2=Conditions, 3=Récapitulatif (bien + diagnostics
//            hérités du logement, lecture seule via _readLogForBail/_lbFill).
// Panels DOM mappés par index → bp-locataire / bp-conditions / bp-recap
// (bp-recap englobe les sections internes bp-bien + bp-diag, non-.tab-panel).
// ═══════════════════════════════════════════════════════════════════
let _bailStep = 1;
let _bailDirty = false;
let _bailIsEdit = false;
const _BAIL_STEPS = ['locataire','conditions','recap'];

function goBailStep(n) {
  // W3 : navigation libre en édition, séquentielle en création
  if(!_bailIsEdit && n > _bailStep + 1) {
    showToast('Terminer d\'abord l\'étape '+(_bailStep+1)+' avant de sauter','info');
    return;
  }
  _bailStep = Math.max(1, Math.min(3, n)); // v15.249 B7 : 3 étapes (Récapitulatif fusionné)
  // Update panels (CSS .tab-panel.act → display:block)
  document.querySelectorAll('#ov-bail .tab-panel').forEach((p,i)=>{
    p.classList.toggle('act', i === _bailStep - 1);
  });
  // Update wizard bar visual state
  document.querySelectorAll('#ov-bail .ws-step').forEach((b,i)=>{
    const n2 = i+1;
    b.classList.toggle('act', n2 === _bailStep);
    b.classList.toggle('done', n2 < _bailStep);
  });
  // Update footer buttons (Précédent / Suivant / Save)
  el('bail-prev-btn').style.display = _bailStep > 1 ? '' : 'none';
  el('bail-next-btn').style.display = _bailStep < 3 ? '' : 'none'; // v15.249 B7 : dernière étape = 3
  el('bail-save-btn').style.display = _bailStep === 3 ? '' : 'none';
  // Scroll panel back to top (UX)
  const body = document.querySelector('#ov-bail .m-body');
  if(body) body.scrollTop = 0;
}
function nextBailStep() {
  // W2 — Soft validation par étape : warn (pas bloquer) avant de passer
  _validateBailStep(_bailStep);
  goBailStep(_bailStep + 1);
}
function prevBailStep() { goBailStep(_bailStep - 1); }

/* Validation soft par étape — affiche des toasts warn mais ne bloque pas
   la progression. La validation bloquante reste dans saveBail (étape 3 finale). */
function _validateBailStep(step) {
  if(step === 1) {
    // Personnes : ≥ 1 locataire avec nom + emails au format si remplis
    const locs = (typeof getBailLocs === 'function') ? getBailLocs().filter(l=>l.nom.trim()) : [];
    if(!locs.length) showToast('⚠️ Aucun locataire saisi','warn');
    const badMail = locs.find(l => l.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(l.email));
    if(badMail) showToast(`⚠️ Email invalide pour ${badMail.nom||'?'} : ${badMail.email}`,'warn');
  } else if(step === 2) {
    // Conditions : HC, charges, dates
    if(pf('b-hc') === 0) showToast('⚠️ Loyer HC à 0 € ou non renseigné','warn');
    if(pf('b-ch') === 0) showToast('⚠️ Charges à 0 € ou non renseignées','warn');
    const _d = v('b-debut'), _f = v('b-fin');
    if(_d && _f && _d > _f) showToast('⚠️ Date début doit être antérieure à date fin','warn');
  }
  // Étape 3 (Récapitulatif : bien + diagnostics hérités, lecture seule) : pas de
  // validation soft. L'étape 3 déclenche saveBail qui valide bloquant ce qui est critique.
}

// W5 : confirmation à la fermeture si modifs non enregistrées
function closeBailWizard() {
  if(_bailDirty && !confirm2('Quitter sans enregistrer ? Les modifications seront perdues.')) return;
  closeM('ov-bail');
  _bailDirty = false;
}

// Tracking dirty : un seul listener délégué sur le body de la modale,
// activé après openBail (sinon tout le pré-remplissage flag dirty)
function _bindBailDirtyTracking() {
  const body = document.querySelector('#ov-bail .m-body');
  if(!body || body.dataset.dirtyBound === '1') return;
  body.dataset.dirtyBound = '1';
  body.addEventListener('input',  ()=>{ _bailDirty = true; });
  body.addEventListener('change', ()=>{ _bailDirty = true; });
}

// ─── Modale Clôturer un bail (extraite de l'ancien onglet "Fin de bail") ─────
function openBailClore(ref) {
  if(!ref) return;
  const bail = DB.baux[ref];
  if(!_isAlive(bail)) { showToast('Bail introuvable','err'); return; } // v15.697 : tombstone = déjà clôturé
  el('b-clore-ref').value = ref;
  el('m-bail-clore-title').textContent = 'Clôturer le bail '+_logLabel(ref);
  // Pré-remplir avec les valeurs existantes si elles ont été saisies par le passé
  el('b-fin-effective').value = bail.finEffective || '';
  el('b-fin-motif').value     = bail.finMotif     || '';
  el('b-loc-nouv-adr').value  = bail.locNouvelleAdr || '';
  el('b-dg-restitue').value   = bail.dgRestitue   || '';
  el('b-dg-retenu').value     = bail.dgRetenu     || '';
  if(el('b-dg-restitue-date')) el('b-dg-restitue-date').value = String(bail.dgRestitueAt || '').slice(0, 10);   // vide tant qu'aucun virement n'est enregistré
  el('b-fin-notes').value     = bail.finNotes     || '';
  openM('ov-bail-clore');
}

// L'UNIQUE écrivain de baux_historique (clôture, relocation) : chaque archive reçoit DÈS sa création un identifiant
// unique `_archiveId` (window.nouvelIdArchive — même format que store-sync._identifierArchives, qui ne réécrit jamais un
// identifiant posé). Deux archives d'un lot le même jour (relocation puis clôture) ne partagent plus leur clé
// (bailHistCle = ref|_archivedAt|_archiveId) : leurs dépôts et leur restitution restent distincts.
function _archiverDansHistorique(rec) {
  if(!DB.baux_historique) DB.baux_historique = [];
  const W = (typeof window !== 'undefined') ? window : null;
  const id = (W && typeof W.nouvelIdArchive === 'function') ? W.nouvelIdArchive() : '';
  const h = Object.assign({}, rec);
  if(id) h._archiveId = id; else delete h._archiveId;
  DB.baux_historique.push(h);
  return h;
}

// Loi n° 89-462 du 6 juillet 1989, article 22 (Légifrance, version en vigueur), alinéas sur le délai de restitution.
const _ART22_RESTITUTION = [
  "Il est restitué dans un délai maximal de deux mois à compter de la remise en main propre, ou par lettre recommandée avec demande d'avis de réception, des clés au bailleur ou à son mandataire, déduction faite, le cas échéant, des sommes restant dues au bailleur et des sommes dont celui-ci pourrait être tenu, aux lieu et place du locataire, sous réserve qu'elles soient dûment justifiées. A cette fin, le locataire indique au bailleur ou à son mandataire, lors de la remise des clés, l'adresse de son nouveau domicile.",
  "Il est restitué dans un délai maximal d'un mois à compter de la remise des clés par le locataire lorsque l'état des lieux de sortie est conforme à l'état des lieux d'entrée, déduction faite, le cas échéant, des sommes restant dues au bailleur et des sommes dont celui-ci pourrait être tenu, en lieu et place du locataire, sous réserve qu'elles soient dûment justifiées."
];
// Clôture d'un bail (saveBailClore, terminerBail) — restitution du dépôt de garantie. Dépôt versé, aucune
// restitution saisie ni déjà enregistrée : AVERTIR (art. 22), jamais bloquer — le dépôt reste compté détenu
// (_dgDetenuDuLot) et sa tâche reste (_computeUnifiedTodo 7bis). Renvoie false si l'utilisateur renonce.
function _clotureDgConfirmer(bail, dateVirement) {
  const dg = bail ? _dgVerseMontant(bail) : 0;   // définition unique : un dépôt non versé n'est ni détenu ni à restituer
  if(dg <= 0 || (bail && bail.dgRestitueAt) || dateVirement) return true;
  return confirm2('Le dépôt de garantie (' + fmt(dg) + ') n\'a pas de date de virement de restitution : il restera compté comme détenu, et sa restitution à faire, jusqu\'à ce qu\'elle soit enregistrée (montants saisis ou non).\n\n'
    + 'Loi n° 89-462 du 6 juillet 1989, article 22 :\n« ' + _ART22_RESTITUTION.join(' »\n« ') + ' »\n\nClôturer quand même ?');
}
// Montants saisis à la clôture. `dgRestitueAt` n'est posé QUE par la date du virement saisie (jamais la date du jour :
// des montants pré-remplis par la régularisation ne disent pas que l'argent est parti). `clotureV: 2` marque une
// clôture de ce déploiement : ses montants ne valent plus restitution (_dgRestitutionEnregistree).
function _clotureDgAppliquer(bail, dgRestitue, dgRetenu, dateVirement) {
  bail.dgRestitue = dgRestitue;
  bail.dgRetenu   = dgRetenu;
  if(dateVirement) bail.dgRestitueAt = String(dateVirement).slice(0, 10);
  bail.clotureV   = 2;
}

function saveBailClore() {
  const ref = el('b-clore-ref').value;
  if(!ref) { showToast('Aucun bail sélectionné','err'); return; }
  const bail = DB.baux[ref];
  if(!_isAlive(bail)) { showToast('Bail introuvable','err'); return; } // v15.697 : tombstone = déjà clôturé
  // Validations bloquantes
  const finEff = v('b-fin-effective');
  const motif  = v('b-fin-motif');
  if(!finEff) { showToast('Date de fin effective requise','err'); return; }
  if(!motif)  { showToast('Motif de fin requis','err'); return; }
  // Confirmation finale (action destructive : archive + vacant)
  if(!confirm2(`Clôturer le bail ${_logLabelRef(ref)} au ${fd(finEff)} ?\nLe logement sera marqué vacant et le bail archivé.`)) return;
  if(!_clotureDgConfirmer(bail, v('b-dg-restitue-date'))) return;
  // Persister les infos de clôture
  bail.finEffective   = finEff;
  bail.finMotif       = motif;
  bail.locNouvelleAdr = v('b-loc-nouv-adr');
  _clotureDgAppliquer(bail, pf('b-dg-restitue'), pf('b-dg-retenu'), v('b-dg-restitue-date'));
  bail.finNotes       = v('b-fin-notes');
  bail.cloture        = true;
  bail.ref            = ref;
  bail._archivedAt    = td();
  // Archiver dans historique + retirer des actifs (v14.71 : tombstone au lieu de delete
  // pour propagation Drive multi-device — sinon le bail réapparaît au merge)
  _archiverDansHistorique(bail);
  DB.baux[ref] = { ref, _deleted: true, _deletedAt: new Date().toISOString(), _modifiedAt: new Date().toISOString(), _archivedAt: td() };
  const log = DB.logements.find(l=>l.ref===ref);
  if(log) { log.locataire = ''; log.fin = finEff; }
  // AUDIT-SUIVI-LOYERS : clôturer les périodes de barème du lot à la date de fin effective
  // (source de vérité du dû — le loyer cesse d'être dû après le départ).
  _baremeCloturerLot(ref, finEff);
  saveDB(); closeM('ov-bail-clore'); initFilters(); rBaux();
  // v15.14 Fix bug refresh : on est probablement sur la fiche logement quand on clôture
  // (bouton "🔚 Clôturer" du panneau Bail LOG-FICHE-360). Sans ce refresh, le bail
  // continue à apparaître comme "en cours" jusqu'au changement de page.
  if (typeof rLogFiche === 'function' && _currentLogFicheRef === ref) rLogFiche();
  if (typeof _rPeriodPage === 'function') _rPeriodPage();
  if (typeof rBiens === 'function') rBiens();
  showToast(`Bail ${_logLabel(ref)} clôturé au ${fd(finEff)}`,'ok');
  _gmbiAlerterSortie(ref, bail, finEff);
}

// ── VISALE-GMBI : alerte PONCTUELLE « déclaration d'occupation » (impots.gouv) ──────────────
// Aucune API DGFiP : l'app dit QUOI déclarer, au moment du changement de locataire, une seule
// fois. Rien n'est persisté (pas de bulle Pilotage, pas d'état « fait »). Le contenu vient du
// module pur js/core/declaration-occupation.js (échéance, catégorie Cerfa, motifs). Jamais
// bloquant : toute erreur est avalée, l'enregistrement du bail est déjà fait.
function _gmbiAfficher(a) {
  if (!a || !el('ov-gmbi') || !el('gmbi-body')) return;
  // Rien de rétroactif (décision Didier 25/09) : un bail ancien saisi après coup, ou un vieux bail
  // clôturé en retard, dont la campagne de déclaration est close → pas d'alerte (audit I-4).
  if (a.echeance && a.echeance <= td()) return;
  const D = window.DeclarationOccupation;
  const vac = a.kind === 'sortie';
  const occ = a.occupants || [];
  const kv = (k, v) => `<div class="k">${k}</div><div class="v">${v}</div>`;
  const occHtml = vac
    ? (occ.length ? kv('Dernier occupant', escHtml(occ.map(o => o.nom).join(', '))) : '') + kv('Date de sortie', escHtml(fd(a.date)))
    : occ.map(o => kv('Occupant', escHtml(o.nom))
        + kv('Né(e) le', (o.ddn ? escHtml(fd(o.ddn)) : '<span class="mu">à compléter</span>') + (o.lieuNaiss ? ' à ' + escHtml(o.lieuNaiss) : ''))).join('')
      + kv('Date d\'entrée dans les lieux', escHtml(fd(a.date)));
  const cat = vac
    ? `<div class="gmbi-pick">${escHtml(a.categorie)} depuis le ${escHtml(fd(a.date))}</div>
       <div class="gmbi-sub">Motif à choisir sur impots.gouv, parmi :</div>
       ${(a.motifs || []).map(m => `<div class="gmbi-opt">${escHtml(m)}</div>`).join('')}
       <div class="mu sm" style="margin-top:6px">Si un nouveau locataire arrive avant la déclaration, déclarer directement le nouvel occupant.</div>`
    : `<div class="gmbi-pick">${escHtml(a.categorie)}<small>Occupé à titre gratuit : <b>Non</b>${a.loyerHC ? ` · loyer mensuel hors charges : <b>${escHtml(fmt(a.loyerHC))}</b> (facultatif)` : ''}</small></div>`;
  const ech = a.echeance ? '1er juillet ' + String(a.echeance).slice(0, 4) : '';
  el('gmbi-body').innerHTML = `
    <div class="mu sm" style="margin-bottom:10px">${escHtml(_logLabel(a.ref))}</div>
    <p style="margin:0 0 12px">À déclarer sur impots.gouv, service « Gérer mes biens immobiliers »${ech ? `, <b>avant le ${escHtml(ech)}</b>` : ''}. Il est possible de déclarer dès maintenant.</p>
    <div class="gmbi-box"><div class="gmbi-h">${_uiIcon('check')} Catégorie à sélectionner</div>${cat}</div>
    <div class="kv-grid" style="margin-top:12px">${occHtml}</div>
    <div class="mu sm" style="margin-top:12px;line-height:1.55">Art. 1418 CGI : déclaration avant le 1er juillet en cas de changement d'occupation. Amende de 150 € par local non déclaré (art. 1770 terdecies CGI). Particulier : espace particulier › Biens immobiliers. Société (SCI…) : espace professionnel › Démarches › « Gérer mes biens immobiliers ». Un garage loué séparément se déclare comme un local distinct.</div>`;
  const lk = el('gmbi-link'); if (lk && D && D.GMBI_URL) lk.href = D.GMBI_URL;
  openM('ov-gmbi');
}
function _gmbiAlerterSortie(ref, bail, dateSortie) {
  try {
    const D = window.DeclarationOccupation; if (!D) return;
    const log = (DB.logements || []).find(l => l && l.ref === ref);
    _gmbiAfficher(D.gmbiAlerteSortie({ log, bail, dateSortie }));
  } catch (e) { console.warn('[GMBI] alerte sortie', e); }
}
function _gmbiAlerterEntree(ref, bail, precedent) {
  try {
    const D = window.DeclarationOccupation; if (!D) return;
    const log = (DB.logements || []).find(l => l && l.ref === ref);
    _gmbiAfficher(D.gmbiAlerteEntree({ log, bail, precedent }));
  } catch (e) { console.warn('[GMBI] alerte entrée', e); }
}

/* v13.02 — réinitialisation des signatures d'un bail (double confirm).
   Permet de re-signer après correction (cas exceptionnel). */
function resetBailSignatures(ref) {
  const bail = DB.baux[ref];
  if(!bail || !bail.signatures || !bail.signatures.signedAt) {
    showToast('Aucune signature à réinitialiser','warn');
    return;
  }
  // Bail signé HORS PROPRYO : pas de signature à effacer — on retire la déclaration (même chemin que la décoche dans « Modifier le
  // bail ») ; elle est archivée dans bail.signaturesAnnulees, jamais détruite.
  if(bail.signatures.mode === 'externe') {
    const ext = { action: 'retirer', prevEtat: 'externe', prevDate: _bailEtatSig(bail).date };
    if(!_bailExterneConfirmer(ext, bail)) return;
    _bailExterneAppliquer(bail, bail, ext, ref);
    _stamp(bail);
    _auditLog('update', 'bail', ref, ref + ' : signé hors Propryo — déclaration retirée');
    saveDB(); rBaux();
    if(typeof _refreshAfterMutation === 'function') _refreshAfterMutation();
    showToast('« Signé hors Propryo » retiré (déclaration conservée dans l\'historique du bail)', 'ok', 6000);
    return;
  }
  const dateStr = fd(bail.signatures.signedAt.slice(0,10));
  // Chantier clôture/relocation (décision II, Didier 28/09) — bail SCELLÉ au cloud (`locked`) : la version
  // signée n'est jamais effacée. Au prochain envoi, sa ligne est ARCHIVÉE (intacte, preuve) et le bail en
  // cours repart en brouillon sur sa propre ligne (store-sync.js, phase 0). Le message dit exactement ça.
  const _scelle = !!bail.signatures.locked;
  const _effet = _scelle
    ? `La version signée est CONSERVÉE : elle est archivée telle quelle (preuve), mais n'est plus affichée comme bail en cours (elle n'est pas encore consultable dans l'app — garder le PDF signé).\nLe bail en cours repart en brouillon, à faire signer de nouveau.`
    : `Toutes les signatures (paraphes + signatures finales + cases « Lu et approuvé ») seront EFFACÉES.\nLe bail redeviendra modifiable.\n\nCette action est irréversible.`;
  if(!confirm(`⚠️ RÉINITIALISER LES SIGNATURES du bail ${_logLabelRef(ref)} ?\n\nSigné le ${dateStr}\n${bail.signatures.nbParaphes||0} pages paraphées\n\n${_effet}`)) return;
  if(!confirm(_scelle
    ? `Confirmation finale : archiver la version signée du bail ${_logLabelRef(ref)} et repartir d'un brouillon à faire signer ?\n\n[OK] = oui\n[Annuler] = ne rien faire`
    : `Confirmation finale : effacer définitivement les signatures du bail ${_logLabelRef(ref)} ?\n\n[OK] = oui, effacer\n[Annuler] = ne rien faire`)) return;
  delete bail.signatures;
  delete bail.annexesDdt;   // DDT annexé : le plan suit les signatures ; recalculé au prochain lancement
  // v14.71 : stamp _modifiedAt pour que le reset se propage aux autres devices via merge Drive
  if(typeof _stamp === 'function') _stamp(bail);
  saveDB();
  rBaux();
  // v15.203 fix : rafraîchir aussi la fiche logement (carte "Bail en cours") si on est dessus.
  // Avant : seul rBaux() (page Baux) était re-rendue → user qui clique depuis la fiche logement
  // voyait l'ancien état (avec bouton "Voir bail signé" + "Réinitialiser") → impression que rien
  // ne se passe. Maintenant : _refreshAfterMutation() rerend log-fiche / imm-fiche / ent-fiche.
  if (typeof _refreshAfterMutation === 'function') _refreshAfterMutation();
  showToast(_scelle
    ? `✅ Version signée du bail ${_logLabel(ref)} archivée (conservée) — le bail en cours est un brouillon à faire signer`
    : `✅ Signatures du bail ${_logLabel(ref)} réinitialisées — bail à nouveau modifiable`,'ok',_scelle?7000:5000);
}

