  if (!logs.length) return banner + '<div style="padding:12px 16px;color:var(--t3,#94a3b8);font-size:13px">Aucun logement' + (q ? ' pour « ' + escHtml(q) + ' »' : ' dans ce périmètre') + '</div>';
  const byImm = {};
