/** v15.221 + v15.222 P1-C — Helper : initiales depuis un nom (pour l'avatar).
 *  Fix audit P1-C : filtre les civilités courantes (M./Mme/Mr/Mlle) pour ne
 *  pas avoir « M. DUPONT Jean » → "MJ" mais → "DJ".
 *
 *  ⚠ v15.230 N3 (audit) — Module ES jumeau testable Vitest :
 *     __tests__/helpers/loc-display.js (avatarInitials + echeanceInfo + bailProgressPct)
 *     TOUTE MODIF de la logique DOIT être répercutée dans les 2 fichiers,
 *     sinon désync silencieuse entre tests Vitest verts et navigateur cassé. */
function _locAvatarInitials(nom) {
  if (!nom) return '?';
  const CIV = /^(M\.?|Mme\.?|Mlle\.?|Mr\.?|Mrs\.?|Dr\.?|Pr\.?|Me\.?)$/i;
  const parts = String(nom).trim().split(/\s+/).filter(p => p && !CIV.test(p));
  if (!parts.length) return '?';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

