  _avenantState={ ref:ref, no:_brouillon?_brouillon.no:window.AvenantRegistre.numeroSuivant(_avenantArgs(ref)), brouillonId:_brouillon?_brouillon.id:null, sel:{}, locNames:[],
    garants:(typeof _bailLegacyToGarants==='function'?_bailLegacyToGarants(bail):[]).map(function(g){ return g.nom||''; }).filter(Boolean) };
  _avenantState.locNames=(bail.locataires&&bail.locataires.length)?bail.locataires.map(function(l){return l.nom||'';}).filter(Boolean):(bail.nom?[bail.nom]:[]);
