function _regRenderPhone(items, totProv, totChar, totSolde, nonRepBanner, to, bailleurArr){
  el('reg-kpis').innerHTML =
      `<div class="rgph-kpi"><div class="v">${fmt(totProv)}</div><div class="l">Provisions</div></div>`
    + `<div class="rgph-kpi"><div class="v neg">${fmt(totChar)}</div><div class="l">Charges réelles</div></div>`
    + `<div class="rgph-kpi"><div class="v ${totSolde>=0?'pos':'neg'}">${totSolde>=0?'+':''}${fmt(totSolde)}</div><div class="l">Solde loc.</div></div>`;
  const byImm={}; items.forEach(r=>{ const k=r.imm||'(sans immeuble)'; (byImm[k]=byImm[k]||[]).push(r); });
  const immNames=Object.keys(byImm).sort((a,b)=>a.localeCompare(b));
  let body='';
  immNames.forEach(imNom=>{
    const grp=byImm[imNom];
    const imVal=_rgIsValidated(imNom, grp.map(r=>r.ref));
    let imBadge;
    if(imVal){ imBadge=`<span class="rgph-bdg ok">${_uiIcon('check',12)}Émise</span>`; }
    else { const _reg=(typeof _rgImmRegime==='function')?_rgImmRegime({imm:imNom,bail:{}}):{copro:false};
      imBadge=_reg.copro
        ? `<span class="rgph-bdg wait">${_uiIcon('hourglass',12)}Arrêté copro</span>`
        : `<span class="rgph-bdg todo">${_uiIcon('warn',12)}À émettre</span>`; }
    body+=`<div class="rgph-imh"><span class="uicw">${_uiIcon('building',15)}</span><span class="nm">${escHtml(imNom)}</span><span class="occ">${grp.length} occ.</span>${imBadge}</div>`;
    body+=`<button type="button" class="rgph-glob" data-imm="${escHtml(imNom)}" onclick="_rgShowGlobal(this.dataset.imm)">${_uiIcon('search',13)}Vue globale (répartition par lot)</button>`;
    grp.forEach(r=>{
      const solde=r.provisions-r.charges;
      const ek=escHtml(r.entryKey);
      const parti=_rgIsParti(r) && !r.isHistorique;
      const per=r.debutOcc?` · ${fd(r.debutOcc)} → ${fd(r.finOcc||to)}`:'';
      const clos=r.isHistorique?`<span class="rgph-clos">Clôturé</span>`:'';
      const tag=solde>=0?`<span class="rgph-tag rest">à restituer</span>`:`<span class="rgph-tag dem">à demander</span>`;
      const nFac=(r.details||[]).length;
      body+=`<div class="rgph-lc" data-ek="${ek}">
        <div class="rgph-lc-top"><span class="rgph-ref">${escHtml(_logLabel(r.ref))}</span>${clos}<span class="rgph-loc">${escHtml(r.loc||'Vacant')}${per}</span>${parti?`<button type="button" class="rgph-more" aria-label="Plus d'actions" onclick="this.closest('.rgph-lc').classList.toggle('open')">${_uiIcon('dots',18)}</button>`:''}</div>
        ${r.forfait?`<div class="rgph-forfait">${escHtml(_rgForfaitLibelle(r.forfait))}</div>`:''}
        <div class="rgph-vals">
          <div class="rgph-v"><div class="k">Provisions</div><div class="n">${fmt(r.provisions)}</div></div>
          <div class="rgph-v"><div class="k">Charges réelles</div><div class="n">${fmt(r.charges)}</div></div>
          <div class="rgph-v solde"><div class="k">Solde</div><div class="n ${solde>=0?'rest':'dem'}">${solde>=0?'+':''}${fmt(solde)}</div>${tag}</div>
        </div>
        <div class="rgph-acts">
          <button type="button" class="pri" data-ek="${ek}" onclick="openRegulDoc(this.dataset.ek)">${_uiIcon('doc-text',14)}Décompte</button>
          <button type="button" data-ek="${ek}" ${imVal?'':'disabled title="Valider l\'immeuble (Vue globale) avant d\'envoyer"'} onclick="envoyerDecompteParEmail(this.dataset.ek)">${_uiIcon('mail',14)}Envoyer</button>
        </div>
        <button type="button" class="rgph-detbtn" aria-expanded="false" onclick="_rgPhToggleDet(this)">${_uiIcon('receipt',14)}Détail des charges<span class="n">${nFac} facture${nFac>1?'s':''}</span></button>
        <div class="rgph-det" hidden>${_rgDetailLocHtml(r)}</div>
        ${parti?`<div class="rgph-moreacts"><button type="button" data-ek="${ek}" onclick="_rgClotureLocataire(this.dataset.ek)">${_uiIcon('flag',14)}Clôturer le partant</button></div>`:''}
      </div>`;
    });
  });
  const total=`<div class="rgph-total"><span>TOTAL — solde net locataires</span><b class="${totSolde>=0?'pos':'neg'}">${totSolde>=0?'+':''}${fmt(totSolde)}</b></div>`;
  // Part bailleur (charges non récupérables — déductibles 2044) : version mobile compacte (lignes empilées, pas de tableau large).
  const bArr=bailleurArr||[];
  const totBail=bArr.reduce((s,b)=>s+(b.total||0),0);
  let bailHtml='';
  if(bArr.length){
    const imms=bArr.map(b=>{
      const segs=(b.segments||[]).slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''))
        .map(seg=>`<div class="rgph-bail-l"><span class="d">${escHtml(fd(seg.date)||'—')}</span><span class="lib">${escHtml(seg.lib||'')}${seg.motif?` <span class="mo">— ${escHtml(seg.motif)}</span>`:''}</span><b>${fmt(seg.montant)}</b></div>`).join('');
      return `<div class="rgph-bail-imm"><b>${escHtml(b.imm)}</b><b class="amt">${fmt(b.total)}</b></div>${segs}`;
    }).join('');
    bailHtml=`<details class="rgph-bail"><summary><span class="uicw">${_uiIcon('bank',15)}</span><span class="tt">Part bailleur <span class="sub">non récupérée · 2044 ligne ${escHtml(_rgLignes2044Bailleur(bArr))}</span></span><b>${fmt(totBail)}</b></summary>`
      + `<div class="rgph-bail-body">${imms}<p class="rgph-bail-note">${_uiIcon('bulb',13)} Non refacturé aux locataires (vacance, lots exclus). 2044 : ligne 225 (location nue), sauf charge déjà déduite sur sa ligne (copropriété : 229).</p></div></details>`;
  }
  el('reg-cards').innerHTML = nonRepBanner + (body ? `<div class="rgph-list">${body}${total}${bailHtml}</div>` : `<div class="rgph-empty">Aucune donnée de régularisation sur la période.</div>${bailHtml}`);
}

function selectAllRegul() {
  document.querySelectorAll('.regul-cb').forEach(cb=>cb.checked=true);
}

function openRegulDoc(entryKey) { _openRegulDoc([entryKey], window._regulFrom, window._regulTo); }

function printSelectedRegul() {
  const keys = [...document.querySelectorAll('.regul-cb:checked')].map(cb=>cb.dataset.ref);
  if(!keys.length) { showToast('Sélectionner au moins un logement','err'); return; }
  _openRegulDoc(keys, window._regulFrom, window._regulTo);
}

/**
 * v15.113 — Build pur du HTML d'un décompte de régul (1 entry).
 * Single source of truth pour 2 renderers : aperçu modale (#regul-doc-content)
 * + PJ email (html2canvas via _rasterizeHtmlToPdfBlob).
 *
 * Copy-paste EXACT du HTML actuel — aucune modification visuelle.
 *
 * @param {string} entryKey - clé entry (logement ref)
 * @param {string} from - date debut ISO
 * @param {string} to - date fin ISO
 * @returns {{html, css, title} | {error}}
 */
// Phase C : acompte de charges (départ) déjà versé pour une entrée régul `r` — dérivé des mouvements
// (catégorie neutre), borné à l'occupation (debutOcc/finOcc → pas de mélange en cas de rotation).
function _regulAcompteDep(r){
  if(!r) return 0;
  // repli aligné sur _rgClotureCompute : si debutOcc/finOcc vides (occDays=0), borne = fenêtre régul courante.
  const from = r.debutOcc || window._regulFrom, to = r.finOcc || window._regulTo;
  return Math.round((DB.mouvements||[])
    .filter(m=>m && !m._deleted && m.cat===_DEPART_ACOMPTE_CAT && m.qui===r.ref && (Number(m.cr)||0)>0 && (!from||m.date>=from) && (!to||m.date<=to))
    .reduce((s,m)=>s+(Number(m.cr)||0),0)*100)/100;
}

function _buildDecompteHtml(entryKey, from, to) {
  const result = computeRegul(from, to);
  const regul = result.entries || {};
  const r = regul[entryKey];
  if (!r) return { error: 'no-entry' };
  const log  = DB.logements.find(l=>l.ref===r.ref);
  const bail = r.bail;
  const ent  = DB.entites.find(e=>e.nom===(bail?.entity||log?.entity));
  // Phase C : imputer l'acompte de charges déjà versé (catégorie neutre) sur le solde définitif.
  const acompteDep = _regulAcompteDep(r);
  const solde = Math.round((r.provisions + acompteDep - r.charges)*100)/100;
  const detailsRows = r.details.map(d=>
    `<tr><td>${fd(d.date)}</td><td>${escHtml(d.lib)}</td><td>${escHtml(d.repartition)}</td><td class="num">${fmtN(d.montant)} €</td></tr>`
  ).join('');
  const occPartiel = r.debutOcc && r.occDays < r.totalDays;
  const occBandeau = occPartiel
    ? `<p style="font-size:11px;margin-top:10px;padding:6px 10px;background:#fffbf0;border-left:3px solid #c9a000;border-radius:2px">
        ⏱ <b>Occupation partielle</b> : ${fd(r.debutOcc)} → ${fd(r.finOcc)} — <b>${r.occDays} jours sur ${r.totalDays}</b> (prorata <b>${Math.round(r.prorata*100)} %</b>)<br>
        <em style="font-size:10px">Les charges communes sont réparties au prorata de la durée d'occupation — décret n°87-713 du 26 août 1987.</em>
       </p>` : '';
  const clotureBadge = r.isHistorique
    ? `<span style="display:inline-block;font-size:10px;padding:2px 8px;background:#e0e0e0;border-radius:8px;color:#555;margin-left:8px">Bail clôturé</span>` : '';
  // Forfait de charges (art. 25-10 / 8-1, V) : transparence sur le document remis au locataire — la part au
  // forfait n'est pas régularisable et a été retirée du présent décompte (charges ET provisions).
  const forfaitBandeau = r.forfait
    ? `<p style="font-size:11px;margin-top:10px;padding:6px 10px;background:#eef4ff;border-left:3px solid #2563eb;border-radius:2px">
        ⓘ <b>Charges au forfait</b> (${escHtml(_rgForfaitRef(r.bail).citation)}) <b>${escHtml(_rgForfaitPeriode(r.forfait))}</b> : cette part <b>n'est pas régularisable</b> et n'entre pas dans le présent décompte.${(r.forfait.excluCharges||r.forfait.excluProvisions)?` <em style="font-size:10px">Non pris en compte au titre du forfait : ${fmtN(r.forfait.excluCharges||0)} € de charges réelles, ${fmtN(r.forfait.excluProvisions||0)} € de provisions.</em>`:''}
       </p>` : '';
  // DOCS-UNIFIES — gabarit unique (variante B). Le fond est repris MOT POUR MOT : objet,
  // article 23, tableau des charges réelles ligne à ligne, provisions/acompte/solde, les
  // quatre mentions légales obligatoires, le bandeau d'occupation partielle et son décret.
  // Seuls les filets gris, les polices et les gouttières changent.
  const corps = `
${_dt('docParties', [
  { label: 'Bailleur', qui: escHtml(ent?.nom||'–'), corps: `<p>${escHtml(ent?.siege||'')}</p>` },
  { label: 'Locataire', qui: `${escHtml(r.loc||log?.locataire||'–')}${clotureBadge}`,
    corps: `<p>${escHtml(bail?.adrBien||log?.adr||'–')}</p>` }
])}
    <p>Objet : Régularisation des charges locatives — ${escHtml(r.ref)}<br>Période du ${fd(from)} au ${fd(to)}</p>
    ${occBandeau}
    ${forfaitBandeau}
    <p>Conformément à l'article 23 de la loi n°89-462 du 6 juillet 1989, nous vous adressons le décompte de régularisation des charges locatives pour la période mentionnée ci-dessus.</p>
    <table class="pro-tbl">
      <tr><th>Date</th><th>Libellé</th><th>Répartition</th><th class="num">Montant</th></tr>
      ${detailsRows||'<tr><td colspan="4" style="text-align:center">Aucune charge enregistrée</td></tr>'}
      <tr class="tot"><td colspan="3">TOTAL charges réelles</td><td class="num">${fmtN(r.charges)} €</td></tr>
    </table>
${_dt('docLignes', [
  { lab:'Provisions versées', val:`${fmtN(r.provisions)} €` },
  acompteDep>0 ? { lab:'Acompte de charges déjà versé', val:`${fmtN(acompteDep)} €` } : null,
  { lab:'Charges réelles', val:`${fmtN(r.charges)} €` },
  { lab:`SOLDE ${solde>=0?'(à votre crédit)':'(à payer)'}`, val:`${solde>=0?'+':''}${fmtN(solde)} €`, tot:true, hi:true }
])}
${_dt('docSignzone', [
  { sig: _docSigOnly(ent), label: 'Le bailleur' }
])}
${_dt('docEncart', `<b>Mentions légales obligatoires</b><br>
      • <b>Justificatifs :</b> les pièces justificatives (factures, contrats d'entretien, relevés de charges de copropriété, etc.) sont tenues à votre disposition pendant <b>six mois</b> à compter de l'envoi du présent décompte — art. 23 al. 3 loi n°89-462 du 6 juillet 1989 (durée portée à six mois par la loi ALUR du 24 mars 2014). Sur demande, l'ensemble des justificatifs disponibles vous est transmis sous forme d'un dossier numérique (.zip).<br>
      • <b>Contestation :</b> en cas de désaccord sur le montant ou la nature des charges, vous pouvez saisir la <b>Commission Départementale de Conciliation (CDC)</b> compétente avant toute action judiciaire — art. 20 loi 89-462.<br>
      • <b>Charges récupérables :</b> les charges portées au présent décompte sont celles figurant sur la liste limitative définie par le <b>décret n°87-713 du 26 août 1987</b> (art. 23 loi 89-462).<br>
      • <b>Communication :</b> le présent décompte est <b>communiqué</b> au locataire ; sa signature n'est pas requise (art. 23 loi 89-462).<br>
      ${solde < 0 ? '• <b>Paiement du solde :</b> le solde appelé est exigible dans le mois suivant l\'envoi du présent décompte (art. 23 al. 4 loi 89-462).' : '• <b>Remboursement :</b> le trop-perçu vous sera restitué dans le mois suivant l\'envoi du présent décompte (art. 23 al. 4 loi 89-462).'}`)}`;

  const html = _docPage(_entiteDeLogement(log), {
    titre: 'Régularisation des charges',
    ctx: `Exercice du ${fd(from)} au ${fd(to)}`,
    corps: corps,
    ref: escHtml(r.ref || ''), date: `Émis le ${fd(td())}`,
    pageBreakAfter: 'always'   // un décompte par destinataire, chacun sa page
  });
  return { html, css: '', title: 'Décompte régul — ' + escHtml(r.ref || '–') };
}
if (typeof window !== 'undefined') window._buildDecompteHtml = _buildDecompteHtml;

function _openRegulDoc(entryKeys, from, to) {
  // v15.113 — utilise le helper _buildDecompteHtml pour 1 entry à la fois, concatène
  // AUDIT M6 — chaque décompte embarque la feuille du gabarit ; à k destinataires, k copies
  // identiques. On ne garde que celle du premier (scopée, donc valable pour tous les autres).
  let _styleVu = false;
  const parts = entryKeys.map(entryKey => {
    const built = _buildDecompteHtml(entryKey, from, to);
    if (built.error) return '';
    if (_styleVu) return built.html.replace(/^<style>[\s\S]*?<\/style>/, '');
    _styleVu = /^<style>/.test(built.html);
    return built.html;
  });
  openM('ov-regul-doc');   // DOC-3 : ouvrir AVANT de rendre (mesure du cadre sandboxé)
  _docRenderSandboxed(el('regul-doc-content'), parts.join('') || '<p class="mu">Aucune donnée</p>', 'Décompte de régularisation', _docCarteCss());
  // DOC-3 : le décompte pose `pageBreakAfter:'always'` pour donner UNE PAGE PAR DESTINATAIRE.
  // Ces sauts vivent désormais dans un document imbriqué : ils ne peuvent plus piloter la
  // pagination de la page parente. On retient le nombre pour AVERTIR à l'impression plutôt que
  // de laisser disparaître une garantie en silence.
  // `entryKeys.length` comptait aussi les destinataires dont le build a échoué (`built.error`
  // → ''), et l'avertissement annonçait 3 destinataires pour 2 documents réellement rendus.
  try { el('regul-doc-content')._docNbDest = parts.filter(Boolean).length || 1; } catch (e) {}
}

// v14.97 EMAIL-AUTO.4 : envoi décompte de régularisation par email.
// Le PDF détaillé reste à imprimer/télécharger via printRegulDoc() ;
// l'email contient la synthèse (provisions / charges réelles / solde) + invite
// à demander les justificatifs (art. 23 al. 3 loi 89-462).
function envoyerDecompteParEmail(entryKey) {
  if (typeof window._openEmailModal !== 'function') {
    showToast('Module email non chargé — vérifier http-server (npx serve)', 'err', 6000);
    return;
  }
  const from = window._regulFrom;
  const to = window._regulTo;
  if (!from || !to) { showToast('Période régul manquante — lancer le calcul d\'abord','err'); return; }
  const result = computeRegul(from, to);
  const r = (result.entries || {})[entryKey];
  if (!r) { showToast('Entrée régul introuvable', 'err'); return; }
  const log = DB.logements.find(l => l.ref === r.ref);
  const bail = r.bail;
  const ent = DB.entites.find(e => e.nom === (bail?.entity || log?.entity));
  const locataire = (bail?.locataires && bail.locataires[0]) || {
    nom: r.loc || log?.locataire || '',
    email: log?.mail || ''
  };
  const acompteDep = _regulAcompteDep(r);
  const solde = Math.round((r.provisions + acompteDep - r.charges)*100)/100;
  const soldeSens = solde >= 0 ? 'à votre crédit (trop-perçu)' : 'à votre charge (complément dû)';
  const soldeAction = solde >= 0
    ? `Le trop-perçu de ${Math.abs(solde).toFixed(2)} € vous sera restitué dans le mois suivant l'envoi du présent décompte (art. 23 al. 4 loi 89-462).`
    : `Le solde de ${Math.abs(solde).toFixed(2)} € est exigible dans le mois suivant l'envoi du présent décompte (art. 23 al. 4 loi 89-462).`;
  const annee = (from || '').slice(0, 4);
  const ctx = {
    locataire,
    bail: bail || { adrBien: log?.adr || '' },
    logement: log || { ref: r.ref },
    entite: ent || {},
    annee,
    provisions: r.provisions.toFixed(2),
    chargesReelles: r.charges.toFixed(2),
    // ligne conditionnelle (vide si pas d'acompte) → cohérence math du corps de l'email avec le solde netté
    acompteLine: acompteDep > 0 ? ('- Acompte de charges déjà versé (imputé) : ' + acompteDep.toFixed(2) + ' €\n') : '',
    solde: Math.abs(solde).toFixed(2),
    soldeSens,
    soldeAction,
    // v15.113 — passer entryKey/from/to pour que _genPdfDecompteRegul appelle _buildDecompteHtml
    entryKey,
    from,
    to
  };
  _docShareOpen('decompte-regul-annuel', ctx, { entityType: 'bail', entityId: r.ref });
}

/**
 * v15.100 EM-2d V1.1 — Wrappers footer modale décompte régul.
 * Récupèrent le 1er entryKey stocké sur #regul-doc-content + délèguent à
 * envoyerDecompteParEmail / _shareDecompteWithPdf.
 */
window._emailDecompteFromModal = function() {
  const host = el('regul-doc-content');
  const keys = host && host._regulEntryKeys;
  if (!keys || !keys.length) { showToast('Aucun décompte sélectionné', 'err'); return; }
  if (keys.length > 1) {
    showToast('Plusieurs baux dans ce décompte — envoi du premier (' + keys[0] + '). Pour les autres, utiliser la liste régul.', 'info', 4500);
  }
  envoyerDecompteParEmail(keys[0]);
};

/**
 * v15.100 EM-2d V1.1 — Partage décompte régul avec PDF (Web Share API niv 2).
 * Pattern identique à _shareQuittanceWithPdf / _shareIRLLetterWithPdf.
 */
window._shareDecompteWithPdf = async function(entryKey) {
  if (!entryKey) {
    const host = el('regul-doc-content');
    const keys = host && host._regulEntryKeys;
    if (!keys || !keys.length) { showToast('Aucun décompte sélectionné', 'err'); return; }
    if (keys.length > 1) {
      showToast('Plusieurs baux dans ce décompte — partage du premier (' + keys[0] + ')', 'info', 4500);
    }
    entryKey = keys[0];
  }
  if (typeof window._emailGenPdfAttachment !== 'function') {
    showToast('Module PDF non chargé (rafraîchir la page)', 'err', 5000);
    return;
  }
  const from = window._regulFrom;
  const to = window._regulTo;
  if (!from || !to) { showToast('Période régul manquante', 'err'); return; }
  const result = computeRegul(from, to);
  const r = (result.entries || {})[entryKey];
  if (!r) { showToast('Entrée régul introuvable', 'err'); return; }
  const log = DB.logements.find(l => l.ref === r.ref);
  const bail = r.bail;
  const ent = DB.entites.find(e => e.nom === (bail?.entity || log?.entity));
  const locataire = (bail?.locataires && bail.locataires[0]) || {
    nom: r.loc || log?.locataire || '', email: log?.mail || ''
  };
  const acompteDep = _regulAcompteDep(r);
  const solde = Math.round((r.provisions + acompteDep - r.charges)*100)/100;
  const annee = (from || '').slice(0, 4);

  showToast('Génération du PDF en cours…', 'info', 2000);
  let pdfResult;
  try {
    const ctx = {
      locataire,
      bail: bail || { adrBien: log?.adr || '' },
      logement: log || { ref: r.ref },
      entite: ent || {},
      annee, from, to,
      provisions: r.provisions.toFixed(2),
      chargesReelles: r.charges.toFixed(2),
      acompteLine: acompteDep > 0 ? ('- Acompte de charges déjà versé (imputé) : ' + acompteDep.toFixed(2) + ' €\n') : '',
      solde: Math.abs(solde).toFixed(2),
      entryKey, // v15.113 — pour que _genPdfDecompteRegul appelle _buildDecompteHtml
      regulEntry: r // legacy support
    };
    pdfResult = await window._emailGenPdfAttachment('decompte-regul-annuel', ctx);
  } catch (e) {
    showToast('Erreur génération PDF : ' + e.message, 'err', 5000);
    return;
  }
  if (pdfResult && pdfResult.error) {
    showToast('Génération PDF échouée : ' + (pdfResult.message || pdfResult.error), 'err', 5000);
    return;
  }

  const bin = atob(pdfResult.base64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const file = new File([bytes], pdfResult.filename, { type: 'application/pdf' });

  const subject = `Décompte de régularisation des charges ${annee} — ${bail?.adrBien || log?.adr || ''}`;
  const body = `Bonjour,\n\nLe décompte de régularisation des charges pour l'année ${annee} est joint en PDF (loi 89-462 art. 23).\n\nProvisions versées : ${r.provisions.toFixed(2)} €\nCharges réelles : ${r.charges.toFixed(2)} €\nSolde : ${solde >= 0 ? '+' : ''}${solde.toFixed(2)} € ${solde >= 0 ? '(à votre crédit)' : '(à régler)'}\n\nLes justificatifs sont tenus à votre disposition pendant un mois (art. 23 al. 3).\n\nCordialement,\n${ent?.gerant || ''}${ent?.nom ? '\n' + ent.nom : ''}`;
  const shareData = { title: subject, text: body, files: [file] };

  if (typeof navigator !== 'undefined' && typeof navigator.share === 'function'
      && typeof navigator.canShare === 'function' && navigator.canShare(shareData)) {
    try {
      await navigator.share(shareData);
      showToast('Partagé ✓ (avec PDF)', 'ok', 3000);
      return;
    } catch (e) {
      if (e && e.name === 'AbortError') return;
      showToast('Erreur partage : ' + (e.message || e), 'err', 4000);
      return;
    }
  }
  try {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url; a.download = pdfResult.filename; a.style.display = 'none';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(subject + '\n\n' + body).catch(() => {});
    }
    showToast('Partage natif indisponible — PDF téléchargé + texte copié', 'ok', 5000);
  } catch (e) {
    showToast('Erreur download : ' + e.message, 'err', 5000);
  }
};

function printRegulDoc() {
  // DOC-3 : l'hôte ne contient plus que le cadre sandboxé — imprimer son `innerHTML` produirait
  // un timbre-poste de 300 px (css/main.css absente de la popup). On repart du document BRUT.
  const host = el('regul-doc-content');
  const fr = host ? host.querySelector('iframe.doc-sandbox') : null;
  // Pas de repli sur `innerHTML` : ce serait le markup DU CADRE, que la popup emboiterait dans
  // un second cadre — le timbre-poste, en silence. Sans document brut, on refuse.
  const corps = host && host._docHtml;
  if (!corps) { showToast('Document indisponible — rouvrir le décompte', 'err'); return; }
  const nbDest = (host && host._docNbDest) || 1;
  if (nbDest > 1 && !confirm2('Ce décompte couvre ' + nbDest + ' destinataires. À l’impression, une page par destinataire n’est pas garantie — la sortie PDF la respecte. Imprimer quand même ?')) return;
  _docPrintSandboxed(corps, 'Décompte charges', fr ? parseInt(fr.style.height, 10) : 0, _docCarteCss());
}
